'use strict';

(() => {
  const X = X21, MC = MC21, FL = FL21;
  const lVertex = X('Vertex', 'Vertex', '頂点', '꼭짓점');
  const lYint = X('$y$-intercept', '$y$-intercept', '$y$切片', '$y$절편');
  PQ.D.push(

    MC(1,
      X('Energi perisai Hunter naik sampai puncak, lalu turun. Grafik energi terhadap waktu berbentuk parabola dengan puncak pada jam ke-4. Energi pada jam ke-1 sama besar dengan energi pada jam ke berapa?',
        'A Hunter\'s shield energy rises to a peak, then falls. The energy-time graph is a parabola with its peak at hour 4. At which hour is the energy equal to the energy at hour 1?',
        'Hunterのシールドのエネルギーは頂点まで増え、その後減ります。エネルギーと時間のグラフは、4時間目に頂点がある放物線です。1時間目と同じエネルギーになるのは何時間目ですか。',
        'Hunter의 방어막 에너지는 정점까지 늘었다가 줄어들어요. 에너지-시간 그래프는 4시간째에 정점이 있는 포물선이에요. 1시간째와 에너지가 같은 때는 몇 시간째일까요?'),
      ['$7$', '$8$', '$5$', '$3$'],
      [X('Jam ke-1 berjarak berapa jam dari puncak (jam ke-4)? Pikirkan: parabola itu simetris terhadap puncaknya.',
          'How many hours is hour 1 from the peak (hour 4)? Think: a parabola is symmetric about its peak.',
          '1時間目は頂点（4時間目）から何時間離れていますか。放物線は頂点を軸に左右対称であることを考えましょう。',
          '1시간째는 정점(4시간째)에서 몇 시간 떨어져 있나요? 포물선은 정점을 기준으로 대칭이라는 점을 생각해 보세요.'),
        X('Jam ke-1 ada di sebelah kiri puncak. Titik yang sama jauhnya di sebelah kanan puncak ada pada jam ke berapa?',
          'Hour 1 is to the left of the peak. At which hour is the point the same distance to the right of the peak?',
          '1時間目は頂点の左側にあります。頂点から同じ距離だけ右側にある点は何時間目ですか。',
          '1시간째는 정점의 왼쪽에 있어요. 정점에서 같은 거리만큼 오른쪽에 있는 점은 몇 시간째일까요?')],
      X('Jam ke-1 berjarak $4 - 1 = 3$ jam di kiri puncak. Sisi kanan yang sama jauhnya: $4 + 3 = 7$. Jadi energinya sama pada jam ke-7.',
        'Hour 1 is $4 - 1 = 3$ hours left of the peak. The same distance on the right: $4 + 3 = 7$. So the energy is equal at hour 7.',
        '1時間目は頂点の左 $4 - 1 = 3$ 時間のところです。右側の同じ距離は $4 + 3 = 7$。よって7時間目に同じエネルギーになります。',
        '1시간째는 정점에서 왼쪽으로 $4 - 1 = 3$시간 떨어져 있어요. 오른쪽으로 같은 거리는 $4 + 3 = 7$. 따라서 7시간째에 에너지가 같아요.')),
    MC(1,
      X('Profit guild naik sampai mencapai profit maksimum, lalu turun lagi saat harga terus dinaikkan. Parabola profit ini terbuka ke arah mana?',
        'A guild\'s profit rises to a maximum, then falls again as the price keeps increasing. Which way does this profit parabola open?',
        'ギルドの利益は最大値まで増え、価格を上げ続けるとまた減ります。この利益の放物線はどの向きに開きますか。',
        '길드의 이익은 최댓값까지 늘었다가 가격을 계속 올리면 다시 줄어요. 이 이익 포물선은 어느 방향으로 열릴까요?'),
      [X('Ke bawah, karena ada nilai maksimum', 'Downward, because there is a maximum value', '下向き。最大値があるから', '아래로. 최댓값이 있기 때문이에요'),
        X('Ke atas, karena profit awalnya kecil', 'Upward, because the profit starts small', '上向き。利益が最初は小さいから', '위로. 이익이 처음에는 작기 때문이에요'),
        X('Ke kanan, karena harga bertambah ke kanan', 'To the right, because the price increases to the right', '右向き。価格は右へ増えるから', '오른쪽으로. 가격이 오른쪽으로 늘어나기 때문이에요'),
        X('Tidak dapat ditentukan', 'Cannot be determined', '決められない', '알 수 없음')],
      [X('Bayangkan grafik profitnya. Titik apa yang menjadi puncaknya: titik tertinggi atau titik terendah?',
          'Picture the profit graph. Is its extreme point the highest point or the lowest point?',
          '利益のグラフを思い浮かべましょう。その端の点は最も高い点ですか、それとも最も低い点ですか。',
          '이익 그래프를 떠올려 보세요. 그 극점은 가장 높은 점인가요, 가장 낮은 점인가요?'),
        X('Parabola yang punya titik tertinggi (nilai maksimum) berbentuk seperti topi. Ke arah mana topi itu terbuka?',
          'A parabola with a highest point (a maximum) looks like a cap. Which way does a cap open?',
          '最も高い点（最大値）をもつ放物線は山の形です。山形はどちらに開いていますか。',
          '가장 높은 점(최댓값)이 있는 포물선은 모자 모양이에요. 모자는 어느 쪽으로 열려 있나요?')],
      X('Profit naik lalu turun berarti ada titik tertinggi, sehingga parabola terbuka ke bawah (koefisien $a$ negatif).',
        'Profit rising then falling means there is a highest point, so the parabola opens downward (coefficient $a$ is negative).',
        '利益が増えてから減るので最も高い点があり、放物線は下向きに開きます（係数 $a$ は負）。',
        '이익이 늘었다가 줄어든다는 것은 가장 높은 점이 있다는 뜻이므로 포물선은 아래로 열려요(계수 $a$ 는 음수).'),
      { 1: ['openDir', { a: -1, dir: 'down' }], 2: ['parabolaHoriz'] }),
    MC(1,
      X('Hunter melompat dan mencapai tinggi maksimum 9 m. Lintasannya parabola yang terbuka ke bawah. Mungkinkah ia pernah mencapai tinggi 10 m?',
        'A Hunter leaps and reaches a maximum height of 9 m. The path is a parabola opening downward. Could the Hunter ever reach a height of 10 m?',
        'Hunterがジャンプして最大の高さ9 mに達します。軌道は下に開く放物線です。10 mの高さに達することはありえますか。',
        'Hunter가 점프해서 최고 높이 9 m에 도달해요. 궤적은 아래로 열린 포물선이에요. 10 m 높이에 닿을 수 있을까요?'),
      [X('Tidak, karena 9 m adalah titik tertinggi', 'No, because 9 m is the highest point', 'いいえ。9 mが最も高い点だから', '아니요. 9 m가 가장 높은 지점이기 때문이에요'),
        X('Ya, karena parabola terus naik', 'Yes, because the parabola keeps rising', 'はい。放物線は上がり続けるから', '네. 포물선은 계속 올라가기 때문이에요'),
        X('Ya, jika ia melompat lebih lama', 'Yes, if the leap lasts longer', 'はい。ジャンプが長く続けば', '네. 점프가 더 오래 이어지면요'),
        X('Tidak, karena tinggi harus selalu 0', 'No, because the height must always be 0', 'いいえ。高さは常に0でなければならないから', '아니요. 높이는 항상 0이어야 하기 때문이에요')],
      [X('Tinggi maksimum itu terjadi di titik apa pada parabola?',
          'At which point of the parabola does the maximum height occur?',
          '最大の高さは放物線のどの点で生じますか。',
          '최대 높이는 포물선의 어느 점에서 생기나요?'),
        X('Pada parabola terbuka ke bawah, apakah ada nilai $y$ yang lebih besar daripada $y$ di vertex?',
          'On a parabola opening downward, is there any $y$-value larger than the $y$ at the vertex?',
          '下に開く放物線で、頂点の $y$ より大きい $y$ の値はありますか。',
          '아래로 열린 포물선에서 꼭짓점의 $y$ 보다 큰 $y$ 값이 있을까요?')],
      X('Pada parabola terbuka ke bawah, nilai $y$ terbesar ada di vertex, yaitu 9. Jadi range-nya $y \\le 9$ dan tinggi 10 m tidak pernah tercapai.',
        'On a parabola opening downward, the largest $y$ is at the vertex, which is 9. So the range is $y \\le 9$ and a height of 10 m is never reached.',
        '下に開く放物線では $y$ の最大値は頂点の9です。よって値域は $y \\le 9$ で、10 mには届きません。',
        '아래로 열린 포물선에서 $y$ 의 최댓값은 꼭짓점의 9예요. 따라서 치역은 $y \\le 9$ 이고 10 m에는 닿지 못해요.'),
      { 1: ['domainRange'], 2: ['domainRange'] }),

    MC(2,
      X('Tabel tinggi belati: $x = -1, 0, 1, 2, 3$ memberi $y = 0, 3, 4, 3, 0$. Vertex parabola ini adalah...',
        'Dagger height table: $x = -1, 0, 1, 2, 3$ gives $y = 0, 3, 4, 3, 0$. The vertex of this parabola is...',
        '短剣の高さの表：$x = -1, 0, 1, 2, 3$ のとき $y = 0, 3, 4, 3, 0$。この放物線の頂点は…',
        '단검 높이 표: $x = -1, 0, 1, 2, 3$ 일 때 $y = 0, 3, 4, 3, 0$. 이 포물선의 꼭짓점은...'),
      ['$(1, 4)$', '$(4, 1)$', '$(-1, 0)$', '$(0, 3)$'],
      [X('Baca nilai $y$ dari kiri ke kanan. Di mana nilainya berhenti naik dan mulai turun?',
          'Read the $y$-values from left to right. Where do they stop rising and start falling?',
          '$y$ の値を左から右へ読みましょう。どこで増えるのをやめて減り始めますか。',
          '$y$ 값을 왼쪽에서 오른쪽으로 읽어 보세요. 어디에서 오르다가 내려가기 시작하나요?'),
        X('Titik balik itu adalah vertex. Ingat urutan penulisan titik: absis $x$ dulu, baru ordinat $y$.',
          'That turning point is the vertex. Remember the order of a point: the $x$-value first, then the $y$-value.',
          'その折り返しの点が頂点です。点の書き方は $x$ 座標が先、$y$ 座標が後です。',
          '그 전환점이 꼭짓점이에요. 점을 쓰는 순서는 $x$ 좌표가 먼저, $y$ 좌표가 나중이에요.')],
      X('Nilai $y$ terbesar adalah 4 pada $x = 1$, dan tabelnya simetris di sekitar $x = 1$ ($y$ pada $x = 0$ dan $x = 2$ sama). Jadi vertex $(1, 4)$.',
        'The largest $y$ is 4 at $x = 1$, and the table is symmetric about $x = 1$ ($y$ is equal at $x = 0$ and $x = 2$). So the vertex is $(1, 4)$.',
        '$y$ の最大値は $x = 1$ のときの4で、表は $x = 1$ について対称です（$x = 0$ と $x = 2$ で $y$ が等しい）。よって頂点は $(1, 4)$。',
        '$y$ 의 최댓값은 $x = 1$ 일 때 4이고, 표는 $x = 1$ 을 기준으로 대칭이에요($x = 0$ 과 $x = 2$ 에서 $y$ 가 같아요). 따라서 꼭짓점은 $(1, 4)$.'),
      { 1: ['swapHK', { h: 1, k: 4 }] }),
    MC(2,
      X('Tabel: $x = 0, 1, 2, 3, 4$ memberi $y = 5, 2, 1, 2, 5$. Fungsi mana yang cocok dengan tabel ini?',
        'Table: $x = 0, 1, 2, 3, 4$ gives $y = 5, 2, 1, 2, 5$. Which function matches this table?',
        '表：$x = 0, 1, 2, 3, 4$ のとき $y = 5, 2, 1, 2, 5$。この表に合う関数はどれですか。',
        '표: $x = 0, 1, 2, 3, 4$ 일 때 $y = 5, 2, 1, 2, 5$. 이 표에 맞는 함수는 어느 것일까요?'),
      ['$y = (x - 2)^2 + 1$', '$y = (x + 2)^2 + 1$', '$y = (x - 1)^2 + 2$', '$y = (x - 2)^2 - 1$'],
      [X('Tentukan dulu vertex dari tabel (nilai $y$ terkecil dan $x$-nya). Lalu ingat bentuk $y = a(x - h)^2 + k$.',
          'First find the vertex from the table (the smallest $y$ and its $x$). Then recall the form $y = a(x - h)^2 + k$.',
          'まず表から頂点（$y$ の最小値とそのときの $x$）を求めましょう。次に $y = a(x - h)^2 + k$ の形を思い出します。',
          '먼저 표에서 꼭짓점($y$ 의 최솟값과 그때의 $x$)을 찾아보세요. 그다음 $y = a(x - h)^2 + k$ 꼴을 떠올려 보세요.'),
        X('Uji satu titik lain, misalnya $x = 0$, pada tiap fungsi. Mana yang menghasilkan $y = 5$ dan juga cocok di $x = 1$?',
          'Test another point, for example $x = 0$, in each function. Which gives $y = 5$ and also fits at $x = 1$?',
          '別の点、たとえば $x = 0$ を各関数で試しましょう。$y = 5$ になり、$x = 1$ でも合うのはどれですか。',
          '다른 점, 예를 들어 $x = 0$ 을 각 함수에 넣어 보세요. $y = 5$ 가 되고 $x = 1$ 에서도 맞는 것은 어느 것일까요?')],
      X('Vertex dari tabel adalah $(2, 1)$, jadi $h = 2$ dan $k = 1$: $y = a(x - 2)^2 + 1$. Cek $x = 0$: $(0 - 2)^2 + 1 = 5$ dan $x = 1$: $(1 - 2)^2 + 1 = 2$. Cocok dengan $a = 1$.',
        'The table\'s vertex is $(2, 1)$, so $h = 2$ and $k = 1$: $y = a(x - 2)^2 + 1$. Check $x = 0$: $(0 - 2)^2 + 1 = 5$ and $x = 1$: $(1 - 2)^2 + 1 = 2$. It fits with $a = 1$.',
        '表の頂点は $(2, 1)$ なので $h = 2$、$k = 1$：$y = a(x - 2)^2 + 1$。$x = 0$ で $(0 - 2)^2 + 1 = 5$、$x = 1$ で $(1 - 2)^2 + 1 = 2$。$a = 1$ で合います。',
        '표의 꼭짓점은 $(2, 1)$ 이므로 $h = 2$, $k = 1$: $y = a(x - 2)^2 + 1$. $x = 0$ 이면 $(0 - 2)^2 + 1 = 5$, $x = 1$ 이면 $(1 - 2)^2 + 1 = 2$. $a = 1$ 일 때 맞아요.'),
      { 1: ['signH', { h: 2, wh: -2 }], 2: ['swapHK', { h: 2, k: 1 }], 3: ['signK', { k: 1, wk: -1 }] }),
    MC(2,
      X('Tabel energi mana: $x = 0, 1, 2, 3, 4, 5, 6$ memberi $y = 0, 5, 8, 9, 8, 5, 0$. Pada interval $x$ mana energi $y$ bertambah (fungsi naik)?',
        'Mana energy table: $x = 0, 1, 2, 3, 4, 5, 6$ gives $y = 0, 5, 8, 9, 8, 5, 0$. On which interval of $x$ does the energy $y$ increase (the function is increasing)?',
        'マナのエネルギーの表：$x = 0, 1, 2, 3, 4, 5, 6$ のとき $y = 0, 5, 8, 9, 8, 5, 0$。エネルギー $y$ が増える（関数が増加する）$x$ の区間はどれですか。',
        '마나 에너지 표: $x = 0, 1, 2, 3, 4, 5, 6$ 일 때 $y = 0, 5, 8, 9, 8, 5, 0$. 에너지 $y$ 가 증가하는(함수가 증가하는) $x$ 구간은 어느 것일까요?'),
      ['$x \\lt 3$', '$x \\gt 3$', '$x \\lt 9$', '$x \\gt 9$'],
      [X('Baca $y$ dari kiri ke kanan. Pada $x$ kecil, nilai $y$ bertambah atau berkurang?',
          'Read $y$ from left to right. For small $x$, does $y$ increase or decrease?',
          '$y$ を左から右へ読みましょう。$x$ が小さいところで $y$ は増えますか、減りますか。',
          '$y$ 를 왼쪽에서 오른쪽으로 읽어 보세요. $x$ 가 작을 때 $y$ 는 늘어나나요, 줄어드나요?'),
        X('Di $x$ berapa nilai $y$ terbesar? Batas naik dan turun ditentukan oleh $x$ vertex, bukan oleh nilai $y$-nya.',
          'At which $x$ is $y$ largest? The boundary between rising and falling is the vertex\'s $x$, not its $y$-value.',
          '$y$ が最大になるのは $x$ がいくつのときですか。増減の境目は頂点の $x$ であって、$y$ の値ではありません。',
          '$y$ 가 가장 큰 때는 $x$ 가 얼마일까요? 증가와 감소의 경계는 꼭짓점의 $x$ 이지 $y$ 값이 아니에요.')],
      X('Dari $x = 0$ sampai $x = 3$, nilai $y$ naik ($0, 5, 8, 9$); setelah $x = 3$ nilainya turun. Jadi fungsi naik pada $x \\lt 3$ (vertex di $x = 3$).',
        'From $x = 0$ to $x = 3$, $y$ rises ($0, 5, 8, 9$); after $x = 3$ it falls. So the function is increasing for $x \\lt 3$ (the vertex is at $x = 3$).',
        '$x = 0$ から $x = 3$ まで $y$ は増え（$0, 5, 8, 9$）、$x = 3$ のあとは減ります。よって関数は $x \\lt 3$ で増加します（頂点は $x = 3$）。',
        '$x = 0$ 에서 $x = 3$ 까지 $y$ 는 늘고($0, 5, 8, 9$), $x = 3$ 이후에는 줄어요. 따라서 함수는 $x \\lt 3$ 에서 증가해요(꼭짓점은 $x = 3$).'),
      { 1: ['openDir', { a: -1, dir: 'down' }], 2: ['useHnotK', { h: 3 }] }),

    MC(3,
      X('Sebuah parabola memiliki vertex $(-2, 5)$ dan melalui titik $(-1, 3)$. Fungsi yang sesuai adalah...',
        'A parabola has vertex $(-2, 5)$ and passes through the point $(-1, 3)$. The matching function is...',
        'ある放物線の頂点は $(-2, 5)$ で、点 $(-1, 3)$ を通ります。合う関数は…',
        '어떤 포물선의 꼭짓점이 $(-2, 5)$ 이고 점 $(-1, 3)$ 을 지나요. 맞는 함수는...'),
      ['$y = -2(x + 2)^2 + 5$', '$y = -2(x - 2)^2 + 5$', '$y = 2(x + 2)^2 + 5$', '$y = -2(x + 2)^2 - 5$'],
      [X('Tulis dulu bentuk $y = a(x - h)^2 + k$ dengan $h$ dan $k$ dari vertex. Nilai $a$ belum diketahui.',
          'First write $y = a(x - h)^2 + k$ using $h$ and $k$ from the vertex. The value of $a$ is still unknown.',
          'まず頂点の $h$ と $k$ を使って $y = a(x - h)^2 + k$ と書きます。$a$ はまだ分かりません。',
          '먼저 꼭짓점의 $h$ 와 $k$ 로 $y = a(x - h)^2 + k$ 를 써 보세요. $a$ 는 아직 몰라요.'),
        X('Titik $(-1, 3)$ harus memenuhi persamaannya. Substitusikan $x = -1$ dan $y = 3$, lalu cari $a$.',
          'The point $(-1, 3)$ must satisfy the equation. Substitute $x = -1$ and $y = 3$, then find $a$.',
          '点 $(-1, 3)$ は式を満たさなければなりません。$x = -1$、$y = 3$ を代入して $a$ を求めましょう。',
          '점 $(-1, 3)$ 은 식을 만족해야 해요. $x = -1$, $y = 3$ 을 대입해서 $a$ 를 구해 보세요.')],
      X('Bentuknya $y = a(x + 2)^2 + 5$. Substitusi $(-1, 3)$: $3 = a(1)^2 + 5$, sehingga $a = -2$. Jadi $y = -2(x + 2)^2 + 5$.',
        'The form is $y = a(x + 2)^2 + 5$. Substituting $(-1, 3)$: $3 = a(1)^2 + 5$, so $a = -2$. Hence $y = -2(x + 2)^2 + 5$.',
        '形は $y = a(x + 2)^2 + 5$。$(-1, 3)$ を代入すると $3 = a(1)^2 + 5$ なので $a = -2$。よって $y = -2(x + 2)^2 + 5$。',
        '꼴은 $y = a(x + 2)^2 + 5$. $(-1, 3)$ 을 대입하면 $3 = a(1)^2 + 5$ 이므로 $a = -2$. 따라서 $y = -2(x + 2)^2 + 5$.'),
      { 1: ['signH', { h: -2, wh: 2 }], 2: ['openDir', { a: -2, dir: 'down' }], 3: ['signK', { k: 5, wk: -5 }] }),
    FL(3,
      X('Parabola $y = a(x - 2)^2 + 1$ melalui titik $(4, 9)$. Tentukan nilai $a$.',
        'The parabola $y = a(x - 2)^2 + 1$ passes through the point $(4, 9)$. Find the value of $a$.',
        '放物線 $y = a(x - 2)^2 + 1$ は点 $(4, 9)$ を通ります。$a$ の値を求めなさい。',
        '포물선 $y = a(x - 2)^2 + 1$ 이 점 $(4, 9)$ 를 지나요. $a$ 의 값을 구하세요.'),
      [{ l: '$a$', r: /^(a=)?2$/ }],
      '$a = 2$',
      [X('Titik $(4, 9)$ terletak pada parabola. Apa yang terjadi pada persamaan jika kamu substitusi $x = 4$ dan $y = 9$?',
          'The point $(4, 9)$ lies on the parabola. What happens to the equation if you substitute $x = 4$ and $y = 9$?',
          '点 $(4, 9)$ は放物線上にあります。$x = 4$、$y = 9$ を代入すると式はどうなりますか。',
          '점 $(4, 9)$ 는 포물선 위에 있어요. $x = 4$, $y = 9$ 를 대입하면 식이 어떻게 될까요?'),
        X('Hitung $(4 - 2)^2$ lebih dulu, lalu selesaikan persamaan linear yang tersisa untuk $a$.',
          'Compute $(4 - 2)^2$ first, then solve the remaining linear equation for $a$.',
          'まず $(4 - 2)^2$ を計算し、残った一次方程式を $a$ について解きます。',
          '먼저 $(4 - 2)^2$ 을 계산하고, 남은 일차방정식을 $a$ 에 대해 풀어 보세요.')],
      X('Substitusi $(4, 9)$: $9 = a(4 - 2)^2 + 1 = 4a + 1$, sehingga $4a = 8$ dan $a = 2$.',
        'Substitute $(4, 9)$: $9 = a(4 - 2)^2 + 1 = 4a + 1$, so $4a = 8$ and $a = 2$.',
        '$(4, 9)$ を代入：$9 = a(4 - 2)^2 + 1 = 4a + 1$ より $4a = 8$、$a = 2$。',
        '$(4, 9)$ 를 대입: $9 = a(4 - 2)^2 + 1 = 4a + 1$ 이므로 $4a = 8$, $a = 2$.')),

    FL(4,
      X('Diketahui $f(x) = -3(x + 2)^2 + 7$. Tentukan vertex dan $y$-intercept-nya.',
        'Given $f(x) = -3(x + 2)^2 + 7$. Find its vertex and $y$-intercept.',
        '$f(x) = -3(x + 2)^2 + 7$ について、頂点と $y$ 切片を求めなさい。',
        '$f(x) = -3(x + 2)^2 + 7$ 이 주어졌어요. 꼭짓점과 $y$절편을 구하세요.'),
      [{ l: lVertex, r: /^\(?-2,7\)?$/ }, { l: lYint, r: /^(\(0,-5\)|-5)$/ }],
      X('$(-2, 7)$ dan $(0, -5)$', '$(-2, 7)$ and $(0, -5)$', '$(-2, 7)$ と $(0, -5)$', '$(-2, 7)$ 와 $(0, -5)$'),
      [X('Bandingkan dengan $y = a(x - h)^2 + k$. Apa nilai $h$ jika kurungnya $(x + 2)$? Ingat tanda di dalam kurung.',
          'Compare with $y = a(x - h)^2 + k$. What is $h$ if the bracket is $(x + 2)$? Mind the sign inside the bracket.',
          '$y = a(x - h)^2 + k$ と比べましょう。括弧が $(x + 2)$ のとき $h$ はいくつですか。括弧の中の符号に注意。',
          '$y = a(x - h)^2 + k$ 와 비교해 보세요. 괄호가 $(x + 2)$ 일 때 $h$ 는 얼마일까요? 괄호 안의 부호에 주의하세요.'),
        X('$y$-intercept didapat dengan substitusi $x = 0$. Hitung kurung, kuadratkan, kalikan $-3$, lalu tambah $7$.',
          'The $y$-intercept comes from substituting $x = 0$. Evaluate the bracket, square it, multiply by $-3$, then add $7$.',
          '$y$ 切片は $x = 0$ を代入して求めます。括弧を計算し、2乗して $-3$ を掛け、$7$ を足しましょう。',
          '$y$절편은 $x = 0$ 을 대입해서 구해요. 괄호를 계산하고 제곱한 뒤 $-3$ 을 곱하고 $7$ 을 더하세요.')],
      X('Dari $y = a(x - h)^2 + k$: $h = -2$ dan $k = 7$, vertex $(-2, 7)$. Substitusi $x = 0$: $f(0) = -3(0 + 2)^2 + 7 = -12 + 7 = -5$, jadi $y$-intercept $(0, -5)$.',
        'From $y = a(x - h)^2 + k$: $h = -2$ and $k = 7$, vertex $(-2, 7)$. Substituting $x = 0$: $f(0) = -3(0 + 2)^2 + 7 = -12 + 7 = -5$, so the $y$-intercept is $(0, -5)$.',
        '$y = a(x - h)^2 + k$ より $h = -2$、$k = 7$ で頂点は $(-2, 7)$。$x = 0$ を代入：$f(0) = -3(0 + 2)^2 + 7 = -12 + 7 = -5$。よって $y$ 切片は $(0, -5)$。',
        '$y = a(x - h)^2 + k$ 에서 $h = -2$, $k = 7$ 이므로 꼭짓점은 $(-2, 7)$. $x = 0$ 을 대입: $f(0) = -3(0 + 2)^2 + 7 = -12 + 7 = -5$, 따라서 $y$절편은 $(0, -5)$.')),
    MC(4,
      X('Tentukan range dari $f(x) = 2(x + 3)^2 - 4$.',
        'Determine the range of $f(x) = 2(x + 3)^2 - 4$.',
        '$f(x) = 2(x + 3)^2 - 4$ の値域を求めなさい。',
        '$f(x) = 2(x + 3)^2 - 4$ 의 치역을 구하세요.'),
      ['$y \\ge -4$', '$y \\le -4$', '$y \\ge -3$', '$y \\ge 4$'],
      [X('Range ditentukan oleh arah bukaan dan nilai $y$ di vertex. Lihat tanda $a$ dan nilai $k$.',
          'The range depends on the opening direction and the $y$-value at the vertex. Look at the sign of $a$ and the value of $k$.',
          '値域は開く向きと頂点の $y$ の値で決まります。$a$ の符号と $k$ の値を見ましょう。',
          '치역은 열리는 방향과 꼭짓점의 $y$ 값으로 정해져요. $a$ 의 부호와 $k$ 의 값을 보세요.'),
        X('Jika $a \\gt 0$, vertex adalah titik terendah, jadi semua $y$ berada di atas atau sama dengan $k$. Baca $k$ apa adanya, tanpa membalik tanda.',
          'If $a \\gt 0$, the vertex is the lowest point, so every $y$ is at least $k$. Read $k$ as it is, without flipping its sign.',
          '$a \\gt 0$ なら頂点が最も低い点なので、すべての $y$ は $k$ 以上です。$k$ は符号を変えずそのまま読みます。',
          '$a \\gt 0$ 이면 꼭짓점이 가장 낮은 점이므로 모든 $y$ 는 $k$ 이상이에요. $k$ 는 부호를 바꾸지 말고 그대로 읽으세요.')],
      X('Karena $a = 2 \\gt 0$, parabola terbuka ke atas dan vertex $(-3, -4)$ adalah titik terendah. Maka range-nya $y \\ge -4$.',
        'Since $a = 2 \\gt 0$, the parabola opens upward and the vertex $(-3, -4)$ is the lowest point. So the range is $y \\ge -4$.',
        '$a = 2 \\gt 0$ なので放物線は上に開き、頂点 $(-3, -4)$ が最も低い点です。したがって値域は $y \\ge -4$。',
        '$a = 2 \\gt 0$ 이므로 포물선은 위로 열리고 꼭짓점 $(-3, -4)$ 가 가장 낮은 점이에요. 따라서 치역은 $y \\ge -4$.'),
      { 1: ['openDir', { a: 2, dir: 'up' }], 2: ['signH', { h: -3, wh: 3 }], 3: ['signK', { k: -4, wk: 4 }] }),
  );
})();

(() => {
  const X = X21, MC = MC21;
  PQ.C.push(

    MC(1,
      X('Hunter melompat dari titik $0$ m, lalu mendarat di tanah pada titik $8$ m. Lintasan lompatannya berbentuk parabola. Pada jarak mendatar berapa Hunter berada di titik tertinggi?',
        'A Hunter jumps from the point $0$ m and lands on the ground at the point $8$ m. The jump path is a parabola. At what horizontal distance is the Hunter at the highest point?',
        'Hunterは $0$ m の地点からジャンプし、$8$ m の地点の地面に着地します。ジャンプの軌道は放物線です。水平距離がいくつのときHunterは最も高い位置にいますか。',
        'Hunter가 $0$ m 지점에서 뛰어올라 $8$ m 지점의 땅에 착지해요. 점프 경로는 포물선이에요. 수평 거리가 얼마일 때 Hunter가 가장 높은 곳에 있을까요?'),
      ['$4$ m', '$8$ m', '$2$ m', '$16$ m'],
      [X('Lompatan itu simetris. Titik tertinggi berada di mana jika dibandingkan dengan titik awal dan titik mendarat?',
          'The jump is symmetric. Where is the highest point compared with the start and the landing point?',
          'ジャンプは左右対称です。最も高い点は、出発点と着地点に対してどこにありますか。',
          '점프는 대칭이에요. 가장 높은 점은 출발점과 착지점에 비해 어디에 있을까요?'),
        X('Sumbu simetri berada di tengah antara $0$ dan $8$. Hitung titik tengahnya.',
          'The axis of symmetry is midway between $0$ and $8$. Find the midpoint.',
          '対称軸は $0$ と $8$ のちょうど中間にあります。中点を求めましょう。',
          '대칭축은 $0$ 과 $8$ 의 한가운데에 있어요. 중점을 구해 보세요.')],
      X('Titik tertinggi terletak di sumbu simetri, tepat di tengah titik awal dan titik mendarat: $\\dfrac{0 + 8}{2} = 4$. Jadi Hunter tertinggi pada jarak $4$ m.',
        'The highest point is on the axis of symmetry, exactly midway between start and landing: $\\dfrac{0 + 8}{2} = 4$. So the Hunter is highest at $4$ m.',
        '最も高い点は対称軸上、出発点と着地点のちょうど中間にあります：$\\dfrac{0 + 8}{2} = 4$。よってHunterが最も高いのは $4$ m の地点です。',
        '가장 높은 점은 대칭축 위, 출발점과 착지점의 한가운데에 있어요: $\\dfrac{0 + 8}{2} = 4$. 따라서 Hunter는 $4$ m 지점에서 가장 높아요.')),
    MC(1,
      X('Belati dilempar ke atas dari menara setinggi $10$ m dan mencapai puncak $15$ m di atas tanah. Pada grafik tinggi terhadap waktu, grafik memotong sumbu tinggi (saat $t = 0$) pada nilai berapa?',
        'A dagger is thrown upward from a tower $10$ m tall and reaches a peak $15$ m above the ground. On the height-time graph, at what value does the graph cross the height axis (at $t = 0$)?',
        '塔の高さ $10$ m から短剣を真上に投げると、地上 $15$ m の高さまで達します。高さと時間のグラフが高さの軸（$t = 0$ のとき）と交わるのは、いくつの値のところですか。',
        '높이 $10$ m 의 탑에서 단검을 위로 던졌더니 지상 $15$ m 에서 정점에 닿았어요. 높이-시간 그래프가 높이 축($t = 0$ 일 때)과 만나는 값은 얼마일까요?'),
      ['$10$', '$15$', '$0$', '$5$'],
      [X('Saat $t = 0$, belati baru saja dilepas. Di ketinggian berapa belati pada saat itu?',
          'At $t = 0$, the dagger has just been released. What height is it at that moment?',
          '$t = 0$ のとき、短剣は手を離れたばかりです。そのときの高さはいくつですか。',
          '$t = 0$ 일 때 단검은 막 손을 떠난 순간이에요. 그때 높이는 얼마일까요?'),
        X('Titik potong sumbu tinggi adalah tinggi awal, bukan tinggi puncak.',
          'The crossing of the height axis is the starting height, not the peak height.',
          '高さの軸との交点は最初の高さであり、頂点の高さではありません。',
          '높이 축과 만나는 점은 처음 높이이지 정점의 높이가 아니에요.')],
      X('Pada $t = 0$ belati ada di tangan Hunter di atas menara, yaitu $10$ m. Nilai $15$ m adalah tinggi puncak, bukan titik potong sumbu tinggi.',
        'At $t = 0$ the dagger is in the Hunter\'s hand on the tower, which is $10$ m. The $15$ m is the peak height, not the crossing of the height axis.',
        '$t = 0$ では短剣は塔の上のHunterの手にあり、高さは $10$ m です。$15$ m は頂点の高さで、軸との交点ではありません。',
        '$t = 0$ 일 때 단검은 탑 위 Hunter의 손에 있으므로 $10$ m 예요. $15$ m 는 정점의 높이이지 축과 만나는 점이 아니에요.')),
    MC(1,
      X('Biaya perawatan Gate turun beberapa hari, lalu naik lagi, sehingga ada biaya terendah. Dalam model $y = ax^2 + bx + c$, tanda $a$ yang cocok adalah...',
        'A Gate\'s upkeep cost falls for some days, then rises again, so there is a lowest cost. In the model $y = ax^2 + bx + c$, the matching sign of $a$ is...',
        'Gateの維持費は数日間下がり、その後また上がるので、最も低い費用があります。モデル $y = ax^2 + bx + c$ で合う $a$ の符号は…',
        'Gate의 유지비는 며칠 동안 내려가다가 다시 올라가서 가장 낮은 비용이 있어요. 모델 $y = ax^2 + bx + c$ 에서 알맞은 $a$ 의 부호는...'),
      [X('Positif, karena parabola terbuka ke atas', 'Positive, because the parabola opens upward', '正。放物線が上に開くから', '양수. 포물선이 위로 열리기 때문이에요'),
        X('Negatif, karena biaya turun dulu', 'Negative, because the cost falls first', '負。費用が先に下がるから', '음수. 비용이 먼저 내려가기 때문이에요'),
        X('Nol, karena grafiknya melengkung', 'Zero, because the graph is curved', '0。グラフが曲がっているから', '0. 그래프가 굽어 있기 때문이에요'),
        X('Tidak dapat ditentukan', 'Cannot be determined', '決められない', '알 수 없음')],
      [X('Ada biaya terendah berarti ada titik terendah pada grafik. Seperti apa bentuk parabola yang punya titik terendah?',
          'A lowest cost means the graph has a lowest point. What shape is a parabola that has a lowest point?',
          '最も低い費用があるということは、グラフに最も低い点があります。最も低い点をもつ放物線はどんな形ですか。',
          '가장 낮은 비용이 있다는 것은 그래프에 가장 낮은 점이 있다는 뜻이에요. 가장 낮은 점이 있는 포물선은 어떤 모양일까요?'),
        X('Parabola yang membuka ke atas (seperti mangkuk) punya titik terendah. Koefisien $a$ yang membuat parabola membuka ke atas bertanda apa?',
          'A parabola opening upward (like a bowl) has a lowest point. What sign must the coefficient $a$ have for it to open upward?',
          '上に開く放物線（お椀の形）には最も低い点があります。放物線が上に開くとき、係数 $a$ の符号は何ですか。',
          '위로 열리는 포물선(그릇 모양)에는 가장 낮은 점이 있어요. 포물선이 위로 열리려면 계수 $a$ 의 부호는 무엇일까요?')],
      X('Biaya terendah berarti titik terendah, sehingga parabola terbuka ke atas. Itu terjadi jika $a \\gt 0$ (positif).',
        'A lowest cost means a lowest point, so the parabola opens upward. That happens when $a \\gt 0$ (positive).',
        '最も低い費用は最も低い点を意味するので、放物線は上に開きます。それは $a \\gt 0$（正）のときです。',
        '가장 낮은 비용은 가장 낮은 점을 뜻하므로 포물선은 위로 열려요. 그것은 $a \\gt 0$ (양수)일 때예요.')),

    MC(2,
      X('Tabel: $x = 0, 1, 2, 3, 4, 5, 6$ memberi $y = 5, 0, -3, -4, -3, 0, 5$. Sumbu simetri parabola ini adalah...',
        'Table: $x = 0, 1, 2, 3, 4, 5, 6$ gives $y = 5, 0, -3, -4, -3, 0, 5$. The axis of symmetry of this parabola is...',
        '表：$x = 0, 1, 2, 3, 4, 5, 6$ のとき $y = 5, 0, -3, -4, -3, 0, 5$。この放物線の対称軸は…',
        '표: $x = 0, 1, 2, 3, 4, 5, 6$ 일 때 $y = 5, 0, -3, -4, -3, 0, 5$. 이 포물선의 대칭축은...'),
      ['$x = 3$', '$x = -4$', '$x = 5$', '$x = 6$'],
      [X('Cari pasangan nilai $y$ yang kembar di kiri dan kanan. Di $x$ mana nilai $y$-nya paling kecil?',
          'Look for matching $y$-values on the left and right. At which $x$ is $y$ smallest?',
          '左右で同じ $y$ の値になる組を探しましょう。$y$ が最も小さいのは $x$ がいくつのときですか。',
          '왼쪽과 오른쪽에서 같은 $y$ 값이 되는 짝을 찾아보세요. $y$ 가 가장 작은 때는 $x$ 가 얼마일까요?'),
        X('Sumbu simetri adalah garis $x = \\ldots$ yang melalui titik terendah, jadi ambil nilai $x$-nya, bukan nilai $y$-nya.',
          'The axis of symmetry is the line $x = \\ldots$ through the lowest point, so take its $x$-value, not its $y$-value.',
          '対称軸は最も低い点を通る直線 $x = \\ldots$ なので、$y$ の値ではなく $x$ の値を使います。',
          '대칭축은 가장 낮은 점을 지나는 직선 $x = \\ldots$ 이므로 $y$ 값이 아니라 $x$ 값을 써야 해요.')],
      X('Nilai $y$ kembar: $x = 2$ dan $x = 4$ sama-sama $-3$, $x = 0$ dan $x = 6$ sama-sama $5$. Titik tengahnya $x = 3$ (nilai $y$ terkecil $-4$). Jadi sumbu simetrinya $x = 3$.',
        'The $y$-values pair up: $x = 2$ and $x = 4$ both give $-3$, and $x = 0$ and $x = 6$ both give $5$. The midpoint is $x = 3$ (smallest $y$ is $-4$). So the axis is $x = 3$.',
        '$y$ の値は対になっています：$x = 2$ と $x = 4$ はどちらも $-3$、$x = 0$ と $x = 6$ はどちらも $5$。中点は $x = 3$（$y$ の最小値は $-4$）。よって対称軸は $x = 3$。',
        '$y$ 값이 짝을 이뤄요: $x = 2$ 와 $x = 4$ 는 모두 $-3$, $x = 0$ 과 $x = 6$ 은 모두 $5$. 중점은 $x = 3$ (가장 작은 $y$ 는 $-4$). 따라서 대칭축은 $x = 3$.'),
      { 1: ['useHnotK', { h: 3 }] }),
    MC(2,
      X('Tabel: $x = 0, 1, 2, 3, 4$ memberi $y = 1, 2, 9, 22, 41$. Selisih kedua nilai $y$ selalu $6$. Berapa koefisien $a$ pada $y = ax^2 + bx + c$?',
        'Table: $x = 0, 1, 2, 3, 4$ gives $y = 1, 2, 9, 22, 41$. The second difference of $y$ is always $6$. What is the coefficient $a$ in $y = ax^2 + bx + c$?',
        '表：$x = 0, 1, 2, 3, 4$ のとき $y = 1, 2, 9, 22, 41$。$y$ の2階差は常に $6$ です。$y = ax^2 + bx + c$ の係数 $a$ はいくつですか。',
        '표: $x = 0, 1, 2, 3, 4$ 일 때 $y = 1, 2, 9, 22, 41$. $y$ 의 이계 차이는 항상 $6$ 이에요. $y = ax^2 + bx + c$ 에서 계수 $a$ 는 얼마일까요?'),
      ['$a = 3$', '$a = 6$', '$a = 12$', '$a = 1$'],
      [X('Selisih kedua pada fungsi kuadrat berkaitan langsung dengan $a$. Apa hubungan keduanya?',
          'In a quadratic function the second difference is directly tied to $a$. What is the relationship?',
          '二次関数では、2階差は $a$ と直接関係しています。その関係は何でしょうか。',
          '이차함수에서 이계 차이는 $a$ 와 직접 관련돼요. 둘의 관계는 무엇일까요?'),
        X('Selisih kedua $= 2a$. Dengan selisih kedua $6$, selesaikan $2a = 6$.',
          'Second difference $= 2a$. With second difference $6$, solve $2a = 6$.',
          '2階差 $= 2a$。2階差が $6$ なので $2a = 6$ を解きましょう。',
          '이계 차이 $= 2a$. 이계 차이가 $6$ 이므로 $2a = 6$ 을 풀어 보세요.')],
      X('Selisih pertama: $1, 7, 13, 19$; selisih kedua: $6, 6, 6$. Pada fungsi kuadrat selisih kedua $= 2a$, jadi $2a = 6$ dan $a = 3$.',
        'First differences: $1, 7, 13, 19$; second differences: $6, 6, 6$. For a quadratic the second difference $= 2a$, so $2a = 6$ and $a = 3$.',
        '1階差：$1, 7, 13, 19$、2階差：$6, 6, 6$。二次関数では2階差 $= 2a$ なので $2a = 6$、$a = 3$。',
        '일계 차이: $1, 7, 13, 19$, 이계 차이: $6, 6, 6$. 이차함수에서 이계 차이 $= 2a$ 이므로 $2a = 6$, $a = 3$.')),
    MC(2,
      X('Tabel: $x = -1, 0, 1, 2, 3$ memberi $y = -5, 1, 3, 1, -5$. Pernyataan yang benar tentang grafiknya adalah...',
        'Table: $x = -1, 0, 1, 2, 3$ gives $y = -5, 1, 3, 1, -5$. The true statement about its graph is...',
        '表：$x = -1, 0, 1, 2, 3$ のとき $y = -5, 1, 3, 1, -5$。そのグラフについて正しい記述は…',
        '표: $x = -1, 0, 1, 2, 3$ 일 때 $y = -5, 1, 3, 1, -5$. 이 그래프에 대해 옳은 설명은...'),
      [X('$y$-intercept $(0, 1)$ dan terbuka ke bawah', '$y$-intercept $(0, 1)$ and opens downward', '$y$ 切片は $(0, 1)$ で、下に開く', '$y$절편은 $(0, 1)$ 이고 아래로 열려요'),
        X('$y$-intercept $(0, 3)$ dan terbuka ke atas', '$y$-intercept $(0, 3)$ and opens upward', '$y$ 切片は $(0, 3)$ で、上に開く', '$y$절편은 $(0, 3)$ 이고 위로 열려요'),
        X('$y$-intercept $(0, 1)$ dan terbuka ke atas', '$y$-intercept $(0, 1)$ and opens upward', '$y$ 切片は $(0, 1)$ で、上に開く', '$y$절편은 $(0, 1)$ 이고 위로 열려요'),
        X('$y$-intercept $(0, -5)$ dan terbuka ke bawah', '$y$-intercept $(0, -5)$ and opens downward', '$y$ 切片は $(0, -5)$ で、下に開く', '$y$절편은 $(0, -5)$ 이고 아래로 열려요')],
      [X('$y$-intercept adalah nilai $y$ ketika $x = 0$. Baca dari tabel. Lalu lihat apakah $y$ terbesar atau terkecil berada di tengah.',
          'The $y$-intercept is the value of $y$ when $x = 0$. Read it from the table. Then see whether the largest or smallest $y$ sits in the middle.',
          '$y$ 切片は $x = 0$ のときの $y$ の値です。表から読みましょう。次に、真ん中にあるのが $y$ の最大か最小かを見ます。',
          '$y$절편은 $x = 0$ 일 때의 $y$ 값이에요. 표에서 읽어 보세요. 그다음 가운데에 있는 것이 $y$ 의 최댓값인지 최솟값인지 보세요.'),
        X('Nilai $y$ naik ke $3$ lalu turun lagi. Parabola dengan titik tertinggi terbuka ke arah mana?',
          'The $y$-values rise to $3$, then fall again. Which way does a parabola with a highest point open?',
          '$y$ の値は $3$ まで増え、その後また減ります。最も高い点をもつ放物線はどちらに開きますか。',
          '$y$ 값이 $3$ 까지 늘었다가 다시 줄어요. 가장 높은 점이 있는 포물선은 어느 쪽으로 열릴까요?')],
      X('Saat $x = 0$, $y = 1$ sehingga $y$-intercept $(0, 1)$. Nilai $y$ tertinggi $3$ berada di tengah ($x = 1$), jadi parabola terbuka ke bawah.',
        'At $x = 0$, $y = 1$, so the $y$-intercept is $(0, 1)$. The highest $y$, $3$, is in the middle ($x = 1$), so the parabola opens downward.',
        '$x = 0$ のとき $y = 1$ なので $y$ 切片は $(0, 1)$。$y$ の最大値 $3$ は真ん中（$x = 1$）にあるので、放物線は下に開きます。',
        '$x = 0$ 일 때 $y = 1$ 이므로 $y$절편은 $(0, 1)$. 가장 큰 $y$ 인 $3$ 이 가운데($x = 1$)에 있으므로 포물선은 아래로 열려요.'),
      { 1: ['yIntC', { c: 1 }], 3: ['yIntC', { c: 1 }] }),
  );
})();

(() => {
  const X = X21, MC = MC21, FL = FL21;
  PQ.C.push(

    MC(3,
      X('Parabola $y = x^2 + bx + c$ memotong sumbu $y$ di $(0, 5)$ dan sumbu simetrinya adalah $x = 2$. Nilai $b$ dan $c$ yang tepat adalah...',
        'The parabola $y = x^2 + bx + c$ crosses the $y$-axis at $(0, 5)$ and its axis of symmetry is $x = 2$. The correct values of $b$ and $c$ are...',
        '放物線 $y = x^2 + bx + c$ は $y$ 軸と $(0, 5)$ で交わり、対称軸は $x = 2$ です。正しい $b$ と $c$ の値は…',
        '포물선 $y = x^2 + bx + c$ 는 $y$축과 $(0, 5)$ 에서 만나고 대칭축은 $x = 2$ 예요. 알맞은 $b$ 와 $c$ 의 값은...'),
      ['$b = -4,\\ c = 5$', '$b = 4,\\ c = 5$', '$b = -2,\\ c = 5$', '$b = -4,\\ c = 2$'],
      [X('Titik potong sumbu $y$ langsung memberi salah satu koefisien. Koefisien yang mana, $b$ atau $c$?',
          'The $y$-intercept directly gives one coefficient. Which one, $b$ or $c$?',
          '$y$ 切片から係数の1つがすぐに分かります。$b$ と $c$ のどちらですか。',
          '$y$절편에서 계수 하나를 바로 알 수 있어요. $b$ 와 $c$ 중 어느 것일까요?'),
        X('Pakai $x = -\\dfrac{b}{2a}$ dengan $a = 1$ dan $x = 2$, lalu selesaikan untuk $b$. Perhatikan tanda minus di depan pecahan.',
          'Use $x = -\\dfrac{b}{2a}$ with $a = 1$ and $x = 2$, then solve for $b$. Mind the minus sign in front of the fraction.',
          '$a = 1$、$x = 2$ として $x = -\\dfrac{b}{2a}$ を使い、$b$ について解きます。分数の前のマイナスに注意しましょう。',
          '$a = 1$, $x = 2$ 로 $x = -\\dfrac{b}{2a}$ 를 써서 $b$ 를 구해 보세요. 분수 앞의 마이너스 부호에 주의하세요.')],
      X('$y$-intercept $(0, c)$ sama dengan $(0, 5)$, jadi $c = 5$. Sumbu simetri: $-\\dfrac{b}{2 \\cdot 1} = 2$, sehingga $b = -4$.',
        'The $y$-intercept $(0, c)$ equals $(0, 5)$, so $c = 5$. Axis: $-\\dfrac{b}{2 \\cdot 1} = 2$, so $b = -4$.',
        '$y$ 切片 $(0, c)$ が $(0, 5)$ なので $c = 5$。対称軸：$-\\dfrac{b}{2 \\cdot 1} = 2$ より $b = -4$。',
        '$y$절편 $(0, c)$ 가 $(0, 5)$ 이므로 $c = 5$. 대칭축: $-\\dfrac{b}{2 \\cdot 1} = 2$ 이므로 $b = -4$.'),
      { 1: ['axisSign', { x: 2, wx: -2 }], 2: ['axisNoHalf', { x: 2 }], 3: ['yIntC', { c: 5 }] }),
    FL(3,
      X('Tabel parabola $y = ax^2 + bx + c$: $x = 0, 1, 2, 3, 4$ memberi $y = 2, 5, 6, 5, 2$. Tentukan $a$, $b$, dan $c$.',
        'Table of the parabola $y = ax^2 + bx + c$: $x = 0, 1, 2, 3, 4$ gives $y = 2, 5, 6, 5, 2$. Find $a$, $b$, and $c$.',
        '放物線 $y = ax^2 + bx + c$ の表：$x = 0, 1, 2, 3, 4$ のとき $y = 2, 5, 6, 5, 2$。$a$、$b$、$c$ を求めなさい。',
        '포물선 $y = ax^2 + bx + c$ 의 표: $x = 0, 1, 2, 3, 4$ 일 때 $y = 2, 5, 6, 5, 2$. $a$, $b$, $c$ 를 구하세요.'),
      [{ l: '$a$', r: /^(a=)?-1$/ }, { l: '$b$', r: /^(b=)?4$/ }, { l: '$c$', r: /^(c=)?2$/ }],
      '$a = -1,\\ b = 4,\\ c = 2$',
      [X('Hitung selisih pertama lalu selisih kedua nilai $y$. Selisih kedua sama dengan $2a$.',
          'Compute the first and then the second differences of $y$. The second difference equals $2a$.',
          '$y$ の1階差、続いて2階差を計算しましょう。2階差は $2a$ に等しくなります。',
          '$y$ 의 일계 차이, 이어서 이계 차이를 구해 보세요. 이계 차이는 $2a$ 와 같아요.'),
        X('$c$ adalah nilai $y$ saat $x = 0$. Setelah $a$ dan $c$ diketahui, substitusi $x = 1$ dan $y = 5$ untuk mencari $b$.',
          '$c$ is the value of $y$ at $x = 0$. Once $a$ and $c$ are known, substitute $x = 1$ and $y = 5$ to find $b$.',
          '$c$ は $x = 0$ のときの $y$ の値です。$a$ と $c$ が分かったら、$x = 1$、$y = 5$ を代入して $b$ を求めます。',
          '$c$ 는 $x = 0$ 일 때의 $y$ 값이에요. $a$ 와 $c$ 를 알았다면 $x = 1$, $y = 5$ 를 대입해서 $b$ 를 구하세요.')],
      X('Selisih pertama: $3, 1, -1, -3$; selisih kedua: $-2$, jadi $2a = -2$ dan $a = -1$. $c = y(0) = 2$. Dari $x = 1$: $-1 + b + 2 = 5$, sehingga $b = 4$.',
        'First differences: $3, 1, -1, -3$; second difference: $-2$, so $2a = -2$ and $a = -1$. $c = y(0) = 2$. From $x = 1$: $-1 + b + 2 = 5$, so $b = 4$.',
        '1階差：$3, 1, -1, -3$、2階差：$-2$ なので $2a = -2$、$a = -1$。$c = y(0) = 2$。$x = 1$ より $-1 + b + 2 = 5$ なので $b = 4$。',
        '일계 차이: $3, 1, -1, -3$, 이계 차이: $-2$ 이므로 $2a = -2$, $a = -1$. $c = y(0) = 2$. $x = 1$ 에서 $-1 + b + 2 = 5$ 이므로 $b = 4$.')),

    FL(4,
      X('Untuk $f(x) = 2x^2 - 8x + 3$, tentukan sumbu simetri, vertex, dan $y$-intercept.',
        'For $f(x) = 2x^2 - 8x + 3$, find the axis of symmetry, the vertex, and the $y$-intercept.',
        '$f(x) = 2x^2 - 8x + 3$ について、対称軸、頂点、$y$ 切片を求めなさい。',
        '$f(x) = 2x^2 - 8x + 3$ 에 대해 대칭축, 꼭짓점, $y$절편을 구하세요.'),
      [{ l: X('Sumbu simetri', 'Axis of symmetry', '対称軸', '대칭축'), r: /^x=2$/ },
        { l: X('Vertex', 'Vertex', '頂点', '꼭짓점'), r: /^\(?2,-5\)?$/ },
        { l: X('$y$-intercept', '$y$-intercept', '$y$切片', '$y$절편'), r: /^(\(0,3\)|3)$/ }],
      '$x = 2$, $(2, -5)$, $(0, 3)$',
      [X('Kenali $a$, $b$, dan $c$ lebih dulu. Lalu pakai $x = -\\dfrac{b}{2a}$ untuk sumbu simetri.',
          'Identify $a$, $b$, and $c$ first. Then use $x = -\\dfrac{b}{2a}$ for the axis of symmetry.',
          'まず $a$、$b$、$c$ を読み取ります。次に対称軸は $x = -\\dfrac{b}{2a}$ を使います。',
          '먼저 $a$, $b$, $c$ 를 찾으세요. 그다음 대칭축은 $x = -\\dfrac{b}{2a}$ 로 구해요.'),
        X('Vertex berada di sumbu simetri: substitusi nilai $x$ itu ke $f$ untuk mendapat $y$. $y$-intercept adalah $f(0)$, yaitu $c$.',
          'The vertex lies on the axis: substitute that $x$ into $f$ to get $y$. The $y$-intercept is $f(0)$, which is $c$.',
          '頂点は対称軸上にあります。その $x$ を $f$ に代入して $y$ を求めます。$y$ 切片は $f(0)$、つまり $c$ です。',
          '꼭짓점은 대칭축 위에 있어요. 그 $x$ 를 $f$ 에 대입해서 $y$ 를 구하세요. $y$절편은 $f(0)$, 즉 $c$ 예요.')],
      X('$a = 2$, $b = -8$, $c = 3$. Sumbu: $x = -\\dfrac{-8}{2 \\cdot 2} = 2$. Vertex: $f(2) = 8 - 16 + 3 = -5$, jadi $(2, -5)$. $y$-intercept $(0, c) = (0, 3)$.',
        '$a = 2$, $b = -8$, $c = 3$. Axis: $x = -\\dfrac{-8}{2 \\cdot 2} = 2$. Vertex: $f(2) = 8 - 16 + 3 = -5$, so $(2, -5)$. The $y$-intercept is $(0, c) = (0, 3)$.',
        '$a = 2$、$b = -8$、$c = 3$。対称軸：$x = -\\dfrac{-8}{2 \\cdot 2} = 2$。頂点：$f(2) = 8 - 16 + 3 = -5$ なので $(2, -5)$。$y$ 切片は $(0, c) = (0, 3)$。',
        '$a = 2$, $b = -8$, $c = 3$. 대칭축: $x = -\\dfrac{-8}{2 \\cdot 2} = 2$. 꼭짓점: $f(2) = 8 - 16 + 3 = -5$ 이므로 $(2, -5)$. $y$절편은 $(0, c) = (0, 3)$.')),
    MC(4,
      X('Tentukan vertex dari $f(x) = -2x^2 + 12x - 7$.',
        'Determine the vertex of $f(x) = -2x^2 + 12x - 7$.',
        '$f(x) = -2x^2 + 12x - 7$ の頂点を求めなさい。',
        '$f(x) = -2x^2 + 12x - 7$ 의 꼭짓점을 구하세요.'),
      ['$(3, 11)$', '$(-3, 11)$', '$(6, -7)$', '$(3, -7)$'],
      [X('Vertex punya dua koordinat. Koordinat $x$ didapat dari $-\\dfrac{b}{2a}$. Hati-hati dengan tanda $a$ dan $b$.',
          'The vertex has two coordinates. The $x$-coordinate comes from $-\\dfrac{b}{2a}$. Be careful with the signs of $a$ and $b$.',
          '頂点には2つの座標があります。$x$ 座標は $-\\dfrac{b}{2a}$ で求めます。$a$ と $b$ の符号に注意しましょう。',
          '꼭짓점에는 좌표가 두 개 있어요. $x$ 좌표는 $-\\dfrac{b}{2a}$ 로 구해요. $a$ 와 $b$ 의 부호에 주의하세요.'),
        X('Setelah mendapat $x$, substitusikan ke $f(x)$ untuk memperoleh $y$. Jangan berhenti di $c$.',
          'Once you have $x$, substitute it into $f(x)$ to get $y$. Do not stop at $c$.',
          '$x$ が求まったら $f(x)$ に代入して $y$ を求めます。$c$ で止めないでください。',
          '$x$ 를 구했으면 $f(x)$ 에 대입해서 $y$ 를 구하세요. $c$ 에서 멈추면 안 돼요.')],
      X('$x = -\\dfrac{12}{2(-2)} = 3$. Lalu $f(3) = -2(9) + 36 - 7 = 11$. Jadi vertex $(3, 11)$ dan karena $a \\lt 0$ itu titik tertinggi.',
        '$x = -\\dfrac{12}{2(-2)} = 3$. Then $f(3) = -2(9) + 36 - 7 = 11$. So the vertex is $(3, 11)$ and, since $a \\lt 0$, it is the highest point.',
        '$x = -\\dfrac{12}{2(-2)} = 3$。次に $f(3) = -2(9) + 36 - 7 = 11$。よって頂点は $(3, 11)$ で、$a \\lt 0$ なので最も高い点です。',
        '$x = -\\dfrac{12}{2(-2)} = 3$. 그다음 $f(3) = -2(9) + 36 - 7 = 11$. 따라서 꼭짓점은 $(3, 11)$ 이고 $a \\lt 0$ 이므로 가장 높은 점이에요.'),
      { 1: ['axisSign', { x: 3, wx: -3 }], 2: ['axisNoHalf', { x: 3 }], 3: ['vertexSubst', { x: 3, y: 11 }] }),
  );
})();

(() => {
  const X = X21, MC = MC21, FL = FL21;
  QADD('D', [

    MC(1,
      X('Hunter A dan Hunter B melempar kristal. Lintasan keduanya parabola terbuka ke bawah dengan bentuk persis sama dan puncak setinggi $10$ m. Puncak A tercapai pada detik ke-2, puncak B pada detik ke-5. Hubungan lintasan keduanya adalah...',
        'Hunter A and Hunter B each throw a crystal. Both paths are downward-opening parabolas of exactly the same shape with a peak of $10$ m. A peaks at second 2, B peaks at second 5. The relation between the two paths is...',
        'HunterAとHunterBがそれぞれ水晶を投げます。2つの軌道は形がまったく同じで下に開く放物線で、頂点の高さはどちらも $10$ m です。Aは2秒目、Bは5秒目に頂点に達します。2つの軌道の関係は…',
        'Hunter A와 Hunter B가 각각 수정을 던져요. 두 경로는 모양이 똑같이 아래로 열린 포물선이고 정점 높이는 모두 $10$ m 예요. A는 2초째, B는 5초째에 정점에 닿아요. 두 경로의 관계는...'),
      [X('Lintasan B adalah lintasan A yang digeser 3 detik ke kanan', 'Path B is path A shifted 3 seconds to the right', 'Bの軌道はAの軌道を右へ3秒ずらしたもの', 'B의 경로는 A의 경로를 오른쪽으로 3초 옮긴 것이에요'),
        X('Lintasan B adalah lintasan A yang digeser 5 detik ke kanan', 'Path B is path A shifted 5 seconds to the right', 'Bの軌道はAの軌道を右へ5秒ずらしたもの', 'B의 경로는 A의 경로를 오른쪽으로 5초 옮긴 것이에요'),
        X('Lintasan B adalah lintasan A yang digeser 3 detik ke kiri', 'Path B is path A shifted 3 seconds to the left', 'Bの軌道はAの軌道を左へ3秒ずらしたもの', 'B의 경로는 A의 경로를 왼쪽으로 3초 옮긴 것이에요'),
        X('Lintasan B adalah lintasan A yang digeser 3 m ke atas', 'Path B is path A shifted 3 m upward', 'Bの軌道はAの軌道を上へ3 mずらしたもの', 'B의 경로는 A의 경로를 위로 3 m 옮긴 것이에요')],
      X('Bandingkan posisi puncak keduanya: tinggi puncak sama, hanya waktunya berbeda. Berapa jauh dan ke arah mana puncak berpindah?',
        'Compare the two peaks: same height, only the time differs. How far and in which direction does the peak move?',
        '2つの頂点を比べましょう。高さは同じで、時刻だけが違います。頂点はどちらへどれだけ動きましたか。',
        '두 정점을 비교해 보세요. 높이는 같고 시간만 달라요. 정점이 어느 쪽으로 얼마나 옮겨졌나요?'),
      X('Tinggi puncak sama ($10$ m), jadi tidak ada pergeseran vertikal. Puncak pindah dari detik ke-2 ke detik ke-5, yaitu $5 - 2 = 3$ detik ke kanan. Jadi B adalah A yang digeser 3 detik ke kanan.',
        'The peak height is the same ($10$ m), so there is no vertical shift. The peak moves from second 2 to second 5, which is $5 - 2 = 3$ seconds to the right. So B is A shifted 3 seconds to the right.',
        '頂点の高さは同じ（$10$ m）なので上下のずれはありません。頂点は2秒目から5秒目へ、$5 - 2 = 3$ 秒だけ右に動きました。したがってBはAを右へ3秒ずらしたものです。',
        '정점 높이가 같으므로($10$ m) 위아래 이동은 없어요. 정점은 2초째에서 5초째로, $5 - 2 = 3$초 오른쪽으로 옮겨졌어요. 따라서 B는 A를 오른쪽으로 3초 옮긴 것이에요.')),
    MC(1,
      X('Lompatan Hunter berbentuk parabola terbuka ke bawah dengan titik tertinggi $9$ m pada jarak $4$ m. Pilih SEMUA pernyataan yang benar.',
        'A Hunter\'s jump is a downward-opening parabola with its highest point of $9$ m at a distance of $4$ m. Select ALL true statements.',
        'Hunterのジャンプは下に開く放物線で、最も高い点は距離 $4$ m のところで高さ $9$ m です。正しい記述をすべて選びなさい。',
        'Hunter의 점프는 아래로 열린 포물선이고 가장 높은 점은 거리 $4$ m 에서 $9$ m 예요. 옳은 설명을 모두 고르세요.'),
      [X('Tinggi $10$ m tidak pernah tercapai', 'A height of $10$ m is never reached', '高さ $10$ m には決して届かない', '높이 $10$ m 에는 절대 닿지 못해요'),
        X('Tinggi pada jarak $3$ m sama dengan tinggi pada jarak $5$ m', 'The height at $3$ m equals the height at $5$ m', '距離 $3$ m での高さは距離 $5$ m での高さと等しい', '거리 $3$ m 에서의 높이는 $5$ m 에서의 높이와 같아요'),
        X('Tinggi pada jarak $5$ m sama dengan tinggi pada jarak $6$ m', 'The height at $5$ m equals the height at $6$ m', '距離 $5$ m での高さは距離 $6$ m での高さと等しい', '거리 $5$ m 에서의 높이는 $6$ m 에서의 높이와 같아요'),
        X('Hunter terus naik setelah jarak $4$ m', 'The Hunter keeps rising after $4$ m', '距離 $4$ m を過ぎても上がり続ける', '거리 $4$ m 이후에도 계속 올라가요')],
      X('Cek tiap pernyataan dengan dua fakta: titik tertinggi adalah $y$ terbesar, dan parabola simetris terhadap sumbunya di $x = 4$.',
        'Check each statement with two facts: the highest point is the largest $y$, and the parabola is symmetric about its axis $x = 4$.',
        '各記述を2つの事実で確かめましょう。最も高い点は $y$ の最大値であり、放物線は軸 $x = 4$ について対称です。',
        '각 설명을 두 가지 사실로 확인하세요. 가장 높은 점은 $y$ 의 최댓값이고, 포물선은 축 $x = 4$ 에 대해 대칭이에요.'),
      X('Benar: $9$ m adalah nilai maksimum sehingga $10$ m tak tercapai, dan $3$ m serta $5$ m sama jauh dari sumbu $x = 4$ sehingga tingginya sama. Salah: $5$ m dan $6$ m tidak sama jauh dari sumbu, dan setelah $4$ m Hunter turun.',
        'True: $9$ m is the maximum so $10$ m is never reached, and $3$ m and $5$ m are equally far from the axis $x = 4$ so the heights are equal. False: $5$ m and $6$ m are not equally far from the axis, and after $4$ m the Hunter descends.',
        '正しい：$9$ m は最大値なので $10$ m には届かず、$3$ m と $5$ m は軸 $x = 4$ から等しい距離にあるので高さが等しい。誤り：$5$ m と $6$ m は軸から等距離ではなく、$4$ m を過ぎると下がります。',
        '옳음: $9$ m 가 최댓값이므로 $10$ m 에는 닿지 못하고, $3$ m 와 $5$ m 는 축 $x = 4$ 에서 같은 거리라 높이가 같아요. 틀림: $5$ m 와 $6$ m 는 축에서 거리가 달라요. 그리고 $4$ m 이후에는 내려가요.'),
      { 3: ['openDir', { a: -1, dir: 'down' }] },
      { multi: 1, a: [0, 1] }),

    MC(2,
      X('Tabel: $x = -3, -2, -1, 0, 1$ memberi $y = -8, 1, 4, 1, -8$. Fungsi vertex form yang cocok dengan tabel ini adalah...',
        'Table: $x = -3, -2, -1, 0, 1$ gives $y = -8, 1, 4, 1, -8$. The vertex-form function that matches this table is...',
        '表：$x = -3, -2, -1, 0, 1$ のとき $y = -8, 1, 4, 1, -8$。この表に合う頂点形の関数は…',
        '표: $x = -3, -2, -1, 0, 1$ 일 때 $y = -8, 1, 4, 1, -8$. 이 표에 맞는 꼭짓점 꼴 함수는...'),
      ['$y = -3(x + 1)^2 + 4$', '$y = -3(x - 1)^2 + 4$', '$y = 3(x + 1)^2 + 4$', '$y = -(x + 1)^2 + 4$'],
      X('Tentukan vertex dari tabel (simetri di mana, $y$ terbesar berapa), lalu uji satu titik lain untuk mencari $a$.',
        'Find the vertex from the table (where the symmetry is, what the largest $y$ is), then test one more point to find $a$.',
        'まず表から頂点（対称の位置と $y$ の最大値）を求め、さらにもう1点で試して $a$ を求めましょう。',
        '먼저 표에서 꼭짓점(대칭 위치와 가장 큰 $y$)을 찾고, 다른 점 하나로 $a$ 를 구해 보세요.'),
      X('Nilai $y$ terbesar $4$ pada $x = -1$, jadi vertex $(-1, 4)$ dan $y = a(x + 1)^2 + 4$. Dari $x = 0$: $a(1)^2 + 4 = 1$, sehingga $a = -3$. Cek $x = -3$: $-3(4) + 4 = -8$. Cocok.',
        'The largest $y$, $4$, is at $x = -1$, so the vertex is $(-1, 4)$ and $y = a(x + 1)^2 + 4$. From $x = 0$: $a(1)^2 + 4 = 1$, so $a = -3$. Check $x = -3$: $-3(4) + 4 = -8$. It fits.',
        '$y$ の最大値 $4$ は $x = -1$ のときなので頂点は $(-1, 4)$、$y = a(x + 1)^2 + 4$。$x = 0$ で $a(1)^2 + 4 = 1$ より $a = -3$。$x = -3$ で確認：$-3(4) + 4 = -8$。合います。',
        '가장 큰 $y$ 인 $4$ 가 $x = -1$ 에 있으므로 꼭짓점은 $(-1, 4)$ 이고 $y = a(x + 1)^2 + 4$. $x = 0$ 에서 $a(1)^2 + 4 = 1$ 이므로 $a = -3$. $x = -3$ 확인: $-3(4) + 4 = -8$. 맞아요.'),
      { 1: ['signH', { h: -1, wh: 1 }], 2: ['openDir', { a: -3, dir: 'down' }] }),
    MC(2,
      X('Dua parabola terbuka ke atas. Tabel P: $x = 0, 1, 2, 3, 4$ memberi $y = 3, 0, -1, 0, 3$. Tabel Q: $x = 0, 1, 2, 3, 4$ memberi $y = 11, 2, -1, 2, 11$. Pernyataan yang benar adalah...',
        'Two parabolas open upward. Table P: $x = 0, 1, 2, 3, 4$ gives $y = 3, 0, -1, 0, 3$. Table Q: $x = 0, 1, 2, 3, 4$ gives $y = 11, 2, -1, 2, 11$. The true statement is...',
        '2つの放物線はどちらも上に開きます。表P：$x = 0, 1, 2, 3, 4$ のとき $y = 3, 0, -1, 0, 3$。表Q：$x = 0, 1, 2, 3, 4$ のとき $y = 11, 2, -1, 2, 11$。正しい記述は…',
        '두 포물선은 모두 위로 열려요. 표 P: $x = 0, 1, 2, 3, 4$ 일 때 $y = 3, 0, -1, 0, 3$. 표 Q: $x = 0, 1, 2, 3, 4$ 일 때 $y = 11, 2, -1, 2, 11$. 옳은 설명은...'),
      [X('Vertex sama $(2, -1)$ dan Q lebih sempit karena $a$ lebih besar', 'Same vertex $(2, -1)$ and Q is narrower because $a$ is larger', '頂点は同じ $(2, -1)$ で、$a$ が大きいのでQのほうが細い', '꼭짓점이 $(2, -1)$ 로 같고 $a$ 가 더 커서 Q가 더 좁아요'),
        X('Vertex sama $(2, -1)$ dan Q lebih lebar karena nilai $y$-nya lebih besar', 'Same vertex $(2, -1)$ and Q is wider because its $y$-values are larger', '頂点は同じ $(2, -1)$ で、$y$ の値が大きいのでQのほうが広い', '꼭짓점이 $(2, -1)$ 로 같고 $y$ 값이 더 커서 Q가 더 넓어요'),
        X('Vertex berbeda karena nilai $y$ keduanya berbeda', 'The vertices differ because the $y$-values differ', '$y$ の値が違うので頂点は異なる', '$y$ 값이 다르므로 꼭짓점도 달라요'),
        X('Q lebih sempit karena $k$-nya lebih besar', 'Q is narrower because its $k$ is larger', '$k$ が大きいのでQのほうが細い', '$k$ 가 더 커서 Q가 더 좁아요')],
      X('Cari vertex tiap tabel, lalu cari $a$ dengan titik $x = 1$ atau $x = 0$. Ingat: lebar parabola ditentukan oleh $|a|$.',
        'Find the vertex of each table, then find $a$ using the point at $x = 1$ or $x = 0$. Remember: the width of a parabola is set by $|a|$.',
        '各表の頂点を求め、$x = 1$ または $x = 0$ の点で $a$ を求めましょう。放物線の幅は $|a|$ で決まることを思い出して。',
        '각 표의 꼭짓점을 찾고 $x = 1$ 또는 $x = 0$ 인 점으로 $a$ 를 구해 보세요. 포물선의 폭은 $|a|$ 가 정해요.'),
      X('Keduanya punya $y$ terkecil $-1$ pada $x = 2$, jadi vertex sama $(2, -1)$. Dari $x = 1$: P memberi $a + (-1) = 0$ sehingga $a = 1$; Q memberi $a - 1 = 2$ sehingga $a = 3$. $|a|$ Q lebih besar, jadi Q lebih sempit.',
        'Both have the smallest $y$, $-1$, at $x = 2$, so the vertex is the same, $(2, -1)$. From $x = 1$: P gives $a + (-1) = 0$ so $a = 1$; Q gives $a - 1 = 2$ so $a = 3$. Q has the larger $|a|$, so Q is narrower.',
        '両方とも $x = 2$ で $y$ が最小の $-1$ なので頂点は同じ $(2, -1)$。$x = 1$ より、Pは $a + (-1) = 0$ で $a = 1$、Qは $a - 1 = 2$ で $a = 3$。Qのほうが $|a|$ が大きいので細いです。',
        '둘 다 $x = 2$ 에서 가장 작은 $y$ 인 $-1$ 을 가지므로 꼭짓점이 $(2, -1)$ 로 같아요. $x = 1$ 에서 P는 $a + (-1) = 0$ 이라 $a = 1$, Q는 $a - 1 = 2$ 라 $a = 3$. Q의 $|a|$ 가 더 크므로 Q가 더 좁아요.'),
      { 1: ['widthA'], 3: ['aVsK'] }),

    FL(3,
      X('Parabola dengan vertex $(-1, 5)$ melalui titik $(1, -3)$. Tentukan $a$ pada $y = a(x - h)^2 + k$ dan nilai $y$ saat $x = 2$.',
        'A parabola with vertex $(-1, 5)$ passes through the point $(1, -3)$. Find $a$ in $y = a(x - h)^2 + k$ and the value of $y$ at $x = 2$.',
        '頂点が $(-1, 5)$ の放物線が点 $(1, -3)$ を通ります。$y = a(x - h)^2 + k$ の $a$ と、$x = 2$ のときの $y$ の値を求めなさい。',
        '꼭짓점이 $(-1, 5)$ 인 포물선이 점 $(1, -3)$ 을 지나요. $y = a(x - h)^2 + k$ 의 $a$ 와 $x = 2$ 일 때의 $y$ 값을 구하세요.'),
      [{ l: '$a$', r: /^(a=)?-2$/ }, { l: X('$y$ saat $x = 2$', '$y$ at $x = 2$', '$x = 2$ のときの $y$', '$x = 2$ 일 때 $y$'), r: /^(y=)?-13$/ }],
      '$a = -2$,\\ $y = -13$',
      X('Tulis $y = a(x + 1)^2 + 5$, substitusikan titik $(1, -3)$ untuk mencari $a$, lalu hitung $y$ pada $x = 2$.',
        'Write $y = a(x + 1)^2 + 5$, substitute the point $(1, -3)$ to find $a$, then compute $y$ at $x = 2$.',
        '$y = a(x + 1)^2 + 5$ と書き、点 $(1, -3)$ を代入して $a$ を求め、$x = 2$ のときの $y$ を計算しましょう。',
        '$y = a(x + 1)^2 + 5$ 로 쓰고 점 $(1, -3)$ 을 대입해 $a$ 를 구한 뒤 $x = 2$ 일 때의 $y$ 를 계산하세요.'),
      X('$y = a(x + 1)^2 + 5$. Substitusi $(1, -3)$: $-3 = 4a + 5$, sehingga $a = -2$. Pada $x = 2$: $y = -2(3)^2 + 5 = -18 + 5 = -13$.',
        '$y = a(x + 1)^2 + 5$. Substituting $(1, -3)$: $-3 = 4a + 5$, so $a = -2$. At $x = 2$: $y = -2(3)^2 + 5 = -18 + 5 = -13$.',
        '$y = a(x + 1)^2 + 5$。$(1, -3)$ を代入：$-3 = 4a + 5$ より $a = -2$。$x = 2$ のとき $y = -2(3)^2 + 5 = -18 + 5 = -13$。',
        '$y = a(x + 1)^2 + 5$. $(1, -3)$ 을 대입: $-3 = 4a + 5$ 이므로 $a = -2$. $x = 2$ 일 때 $y = -2(3)^2 + 5 = -18 + 5 = -13$.')),
    MC(3,
      X('Grafik $y = x^2$ digeser $4$ satuan ke kanan dan $3$ satuan ke bawah, lalu hasilnya dicerminkan terhadap sumbu $x$. Persamaan grafik akhir adalah...',
        'The graph of $y = x^2$ is shifted $4$ units right and $3$ units down, and the result is then reflected in the $x$-axis. The equation of the final graph is...',
        '$y = x^2$ のグラフを右に $4$、下に $3$ 平行移動し、その結果を $x$ 軸について対称に折り返します。最終的なグラフの式は…',
        '$y = x^2$ 의 그래프를 오른쪽으로 $4$, 아래로 $3$ 옮긴 뒤 그 결과를 $x$축에 대해 대칭이동해요. 최종 그래프의 식은...'),
      ['$y = -(x - 4)^2 + 3$', '$y = -(x - 4)^2 - 3$', '$y = -(x + 4)^2 + 3$', '$y = (x - 4)^2 + 3$'],
      X('Geser dulu: tulis persamaannya. Pencerminan terhadap sumbu $x$ mengubah $y$ menjadi $-y$ untuk seluruh ruas kanan, termasuk $k$.',
        'Shift first and write the equation. Reflection in the $x$-axis changes $y$ into $-y$ for the whole right-hand side, including $k$.',
        'まず平行移動した式を書きます。$x$ 軸対称では右辺全体が $-1$ 倍になり、$k$ も符号が変わります。',
        '먼저 이동한 식을 쓰세요. $x$축 대칭은 우변 전체에 $-1$ 을 곱하므로 $k$ 의 부호도 바뀌어요.'),
      X('Setelah digeser: $y = (x - 4)^2 - 3$ dengan vertex $(4, -3)$. Pencerminan terhadap sumbu $x$ mengalikan seluruh ruas dengan $-1$: $y = -[(x - 4)^2 - 3] = -(x - 4)^2 + 3$. Vertex menjadi $(4, 3)$, terbuka ke bawah.',
        'After the shift: $y = (x - 4)^2 - 3$ with vertex $(4, -3)$. Reflecting in the $x$-axis multiplies the whole expression by $-1$: $y = -[(x - 4)^2 - 3] = -(x - 4)^2 + 3$. The vertex becomes $(4, 3)$ and it opens downward.',
        '平行移動後：$y = (x - 4)^2 - 3$、頂点は $(4, -3)$。$x$ 軸対称は式全体を $-1$ 倍します：$y = -[(x - 4)^2 - 3] = -(x - 4)^2 + 3$。頂点は $(4, 3)$ で下に開きます。',
        '이동 후: $y = (x - 4)^2 - 3$, 꼭짓점은 $(4, -3)$. $x$축 대칭은 식 전체에 $-1$ 을 곱해요: $y = -[(x - 4)^2 - 3] = -(x - 4)^2 + 3$. 꼭짓점은 $(4, 3)$ 이고 아래로 열려요.'),
      { 1: ['signK', { k: 3, wk: -3 }], 2: ['signH', { h: 4, wh: -4 }], 3: ['openDir', { a: -1, dir: 'down' }] }),

    MC(4,
      X('Perhatikan $f(x) = -2(x - 3)^2 + 8$. Pernyataan yang benar adalah...',
        'Consider $f(x) = -2(x - 3)^2 + 8$. The true statement is...',
        '$f(x) = -2(x - 3)^2 + 8$ について、正しい記述は…',
        '$f(x) = -2(x - 3)^2 + 8$ 을 보세요. 옳은 설명은...'),
      [X('Nilai maksimum $8$ di $x = 3$ dan $y$-intercept $(0, -10)$', 'Maximum value $8$ at $x = 3$ and $y$-intercept $(0, -10)$', '最大値 $8$（$x = 3$ のとき）、$y$ 切片は $(0, -10)$', '$x = 3$ 에서 최댓값 $8$, $y$절편은 $(0, -10)$'),
        X('Nilai maksimum $3$ di $x = 8$ dan $y$-intercept $(0, -10)$', 'Maximum value $3$ at $x = 8$ and $y$-intercept $(0, -10)$', '最大値 $3$（$x = 8$ のとき）、$y$ 切片は $(0, -10)$', '$x = 8$ 에서 최댓값 $3$, $y$절편은 $(0, -10)$'),
        X('Nilai maksimum $8$ di $x = 3$ dan $y$-intercept $(0, 8)$', 'Maximum value $8$ at $x = 3$ and $y$-intercept $(0, 8)$', '最大値 $8$（$x = 3$ のとき）、$y$ 切片は $(0, 8)$', '$x = 3$ 에서 최댓값 $8$, $y$절편은 $(0, 8)$'),
        X('Nilai minimum $8$ di $x = 3$ dan $y$-intercept $(0, -10)$', 'Minimum value $8$ at $x = 3$ and $y$-intercept $(0, -10)$', '最小値 $8$（$x = 3$ のとき）、$y$ 切片は $(0, -10)$', '$x = 3$ 에서 최솟값 $8$, $y$절편은 $(0, -10)$')],
      X('Baca $a$, $h$, $k$ dulu: tanda $a$ menentukan maksimum atau minimum, vertex $(h, k)$ memberi nilai dan lokasinya. $y$-intercept memakai $x = 0$.',
        'Read $a$, $h$, $k$ first: the sign of $a$ decides maximum or minimum, the vertex $(h, k)$ gives the value and its location. The $y$-intercept uses $x = 0$.',
        'まず $a$、$h$、$k$ を読み取ります。$a$ の符号で最大か最小かが決まり、頂点 $(h, k)$ が値とその位置を与えます。$y$ 切片は $x = 0$ を使います。',
        '먼저 $a$, $h$, $k$ 를 읽으세요. $a$ 의 부호가 최대인지 최소인지 정하고, 꼭짓점 $(h, k)$ 가 값과 위치를 알려 줘요. $y$절편은 $x = 0$ 을 써요.'),
      X('$a = -2 \\lt 0$, jadi ada nilai maksimum $k = 8$ di $x = h = 3$. $f(0) = -2(0 - 3)^2 + 8 = -18 + 8 = -10$, jadi $y$-intercept $(0, -10)$.',
        '$a = -2 \\lt 0$, so there is a maximum value $k = 8$ at $x = h = 3$. $f(0) = -2(0 - 3)^2 + 8 = -18 + 8 = -10$, so the $y$-intercept is $(0, -10)$.',
        '$a = -2 \\lt 0$ なので $x = h = 3$ で最大値 $k = 8$ をとります。$f(0) = -2(0 - 3)^2 + 8 = -18 + 8 = -10$ より $y$ 切片は $(0, -10)$。',
        '$a = -2 \\lt 0$ 이므로 $x = h = 3$ 에서 최댓값 $k = 8$ 을 가져요. $f(0) = -2(0 - 3)^2 + 8 = -18 + 8 = -10$ 이므로 $y$절편은 $(0, -10)$.'),
      { 1: ['swapHK', { h: 3, k: 8 }], 2: ['yIntSubst', { e: 'f(0) = -2(0 - 3)^2 + 8', y: -10 }], 3: ['openDir', { a: -2, dir: 'down' }] }),
  ]);
})();

(() => {
  const X = X21, MC = MC21, FL = FL21;
  QADD('C', [

    MC(1,
      X('Belati sihir Hunter melintas dalam lintasan parabola. Ketinggiannya sama, $15$ m, ketika jarak mendatarnya $3$ m dan $11$ m. Pada jarak mendatar berapa belati berada paling tinggi?',
        'A Hunter\'s magic dagger flies along a parabolic path. Its height is the same, $15$ m, when the horizontal distance is $3$ m and $11$ m. At what horizontal distance is the dagger highest?',
        'Hunterの魔法の短剣が放物線の軌道を飛びます。水平距離が $3$ m と $11$ m のとき、高さはどちらも $15$ m で同じです。水平距離がいくつのとき短剣は最も高くなりますか。',
        'Hunter의 마법 단검이 포물선 경로로 날아가요. 수평 거리가 $3$ m 와 $11$ m 일 때 높이는 둘 다 $15$ m 로 같아요. 수평 거리가 얼마일 때 단검이 가장 높을까요?'),
      ['$7$ m', '$14$ m', '$4$ m', '$15$ m'],
      X('Dua titik dengan tinggi sama berjarak sama dari sumbu simetri. Di mana letak sumbu itu terhadap kedua titik?',
        'Two points at the same height are equally far from the axis of symmetry. Where is the axis relative to the two points?',
        '同じ高さの2点は対称軸から等しい距離にあります。対称軸は2点に対してどこにありますか。',
        '높이가 같은 두 점은 대칭축에서 같은 거리에 있어요. 대칭축은 두 점에 비해 어디에 있을까요?'),
      X('Tinggi yang sama berarti kedua titik simetris terhadap sumbu, jadi sumbu ada di tengahnya: $\\dfrac{3 + 11}{2} = 7$. Titik tertinggi ada di sumbu, yaitu pada jarak $7$ m. Angka $15$ m adalah tingginya, bukan jaraknya.',
        'The same height means the two points are symmetric about the axis, so the axis is midway: $\\dfrac{3 + 11}{2} = 7$. The highest point is on the axis, at a distance of $7$ m. The $15$ m is the height, not the distance.',
        '高さが同じなので2点は軸について対称で、軸はその中間にあります：$\\dfrac{3 + 11}{2} = 7$。最も高い点は軸上、つまり距離 $7$ m のところです。$15$ m は高さであって距離ではありません。',
        '높이가 같다는 것은 두 점이 축에 대해 대칭이라는 뜻이라 축은 그 한가운데예요: $\\dfrac{3 + 11}{2} = 7$. 가장 높은 점은 축 위, 즉 거리 $7$ m 에 있어요. $15$ m 는 높이이지 거리가 아니에요.'),
      { 1: ['axisNoHalf', { x: 7 }] }),
    MC(1,
      X('Belati dilempar dari menara setinggi $12$ m. Dua detik kemudian belati mencapai puncak $20$ m, lalu turun. Pada detik keberapa belati kembali setinggi menara ($12$ m)?',
        'A dagger is thrown from a tower $12$ m high. Two seconds later it reaches its peak of $20$ m, then falls. At which second is the dagger back at the tower\'s height ($12$ m)?',
        '高さ $12$ m の塔から短剣を投げます。2秒後に頂点の $20$ m に達し、その後落ちていきます。何秒後に短剣は塔と同じ高さ（$12$ m）に戻りますか。',
        '높이 $12$ m 의 탑에서 단검을 던져요. 2초 뒤에 정점 $20$ m 에 닿고 그다음 내려와요. 몇 초째에 단검이 탑과 같은 높이($12$ m)로 돌아올까요?'),
      [X('$4$ detik', '$4$ seconds', '$4$ 秒', '$4$초'),
        X('$2$ detik', '$2$ seconds', '$2$ 秒', '$2$초'),
        X('$8$ detik', '$8$ seconds', '$8$ 秒', '$8$초'),
        X('$20$ detik', '$20$ seconds', '$20$ 秒', '$20$초')],
      X('Saat $t = 0$ tingginya $12$ m. Sumbu simetri ada di puncak, yaitu $t = 2$. Titik $12$ m yang lain berada sejauh mana dari sumbu?',
        'At $t = 0$ the height is $12$ m. The axis of symmetry is at the peak, $t = 2$. How far from the axis is the other $12$ m point?',
        '$t = 0$ のとき高さは $12$ m です。対称軸は頂点の $t = 2$ にあります。もう1つの $12$ m の点は軸からどれだけ離れていますか。',
        '$t = 0$ 일 때 높이는 $12$ m 예요. 대칭축은 정점인 $t = 2$ 에 있어요. 다른 $12$ m 지점은 축에서 얼마나 떨어져 있을까요?'),
      X('Titik awal $t = 0$ berjarak $2$ dari sumbu $t = 2$. Titik dengan tinggi sama ada di sisi lain sumbu pada jarak yang sama, yaitu $t = 2 + 2 = 4$. Jadi belati kembali setinggi menara pada detik ke-4.',
        'The starting point $t = 0$ is $2$ away from the axis $t = 2$. The point of equal height is on the other side of the axis at the same distance: $t = 2 + 2 = 4$. So the dagger is back at the tower\'s height at second 4.',
        '出発点 $t = 0$ は軸 $t = 2$ から $2$ 離れています。同じ高さの点は軸の反対側で同じ距離のところ、つまり $t = 2 + 2 = 4$ です。よって短剣は4秒後に塔と同じ高さに戻ります。',
        '출발점 $t = 0$ 은 축 $t = 2$ 에서 $2$ 떨어져 있어요. 높이가 같은 점은 축의 반대편 같은 거리, 즉 $t = 2 + 2 = 4$ 에 있어요. 따라서 단검은 4초째에 탑과 같은 높이로 돌아와요.')),
    MC(1,
      X('Profit guild (juta) dari penjualan $x$ puluh kristal mana berbentuk parabola. Profit $0$ saat $x = 0$ dan $x = 10$, dan profit tertinggi $25$ juta saat $x = 5$. Pilih SEMUA pernyataan yang benar.',
        'The guild profit (millions) from selling $x$ tens of mana crystals is a parabola. The profit is $0$ at $x = 0$ and $x = 10$, and the highest profit is $25$ million at $x = 5$. Select ALL true statements.',
        '魔力水晶を $x$ 十個売ったときのギルドの利益（百万）は放物線になります。利益は $x = 0$ と $x = 10$ で $0$、最大の利益は $x = 5$ のときの $25$ 百万です。正しい記述をすべて選びなさい。',
        '마나 수정을 $x$ 십 개 팔았을 때 길드의 이익(백만)은 포물선 모양이에요. 이익은 $x = 0$ 과 $x = 10$ 에서 $0$ 이고, 가장 큰 이익은 $x = 5$ 일 때 $25$ 백만이에요. 옳은 설명을 모두 고르세요.'),
      [X('Profit saat $x = 2$ sama dengan profit saat $x = 8$', 'The profit at $x = 2$ equals the profit at $x = 8$', '$x = 2$ のときの利益は $x = 8$ のときの利益と等しい', '$x = 2$ 일 때의 이익은 $x = 8$ 일 때의 이익과 같아요'),
        X('Profit maksimum $25$ juta tercapai saat $x = 5$', 'The maximum profit of $25$ million is reached at $x = 5$', '最大利益 $25$ 百万は $x = 5$ のときに得られる', '최대 이익 $25$ 백만은 $x = 5$ 일 때 얻어져요'),
        X('Profit saat $x = 3$ sama dengan profit saat $x = 6$', 'The profit at $x = 3$ equals the profit at $x = 6$', '$x = 3$ のときの利益は $x = 6$ のときの利益と等しい', '$x = 3$ 일 때의 이익은 $x = 6$ 일 때의 이익과 같아요'),
        X('Profit terus naik setelah $x = 5$', 'The profit keeps rising after $x = 5$', '$x = 5$ を過ぎても利益は上がり続ける', '$x = 5$ 이후에도 이익이 계속 올라가요'),
        X('Guild rugi untuk semua $x$ di antara $0$ dan $10$', 'The guild loses money for every $x$ between $0$ and $10$', '$0$ と $10$ の間のすべての $x$ でギルドは赤字になる', '$0$ 과 $10$ 사이의 모든 $x$ 에서 길드는 손해를 봐요')],
      X('Profit $0$ di $x = 0$ dan $x = 10$ berarti sumbu simetri ada di tengahnya. Gunakan simetri untuk membandingkan, dan ingat puncaknya adalah profit terbesar.',
        'Profit $0$ at $x = 0$ and $x = 10$ means the axis is midway. Use symmetry to compare, and remember the peak is the largest profit.',
        '$x = 0$ と $x = 10$ で利益が $0$ なので、対称軸はその中間です。対称性で比べ、頂点が利益の最大値であることを思い出しましょう。',
        '$x = 0$ 과 $x = 10$ 에서 이익이 $0$ 이므로 축은 그 한가운데예요. 대칭을 이용해 비교하고, 정점이 가장 큰 이익임을 기억하세요.'),
      X('Sumbu simetri $x = 5$ dan $y$ maksimum $25$ di sana. Benar: $x = 2$ dan $x = 8$ sama jauh ($3$) dari sumbu sehingga profitnya sama, dan puncaknya $25$ juta di $x = 5$. Salah: $x = 3$ dan $x = 6$ tidak sama jauh dari sumbu, setelah $x = 5$ profit turun, dan di antara $0$ dan $10$ profit positif (parabola di atas sumbu $x$).',
        'The axis is $x = 5$ and the maximum $y$ is $25$ there. True: $x = 2$ and $x = 8$ are equally far ($3$) from the axis so the profits are equal, and the peak is $25$ million at $x = 5$. False: $x = 3$ and $x = 6$ are not equally far from the axis, after $x = 5$ the profit falls, and between $0$ and $10$ the profit is positive (the parabola is above the $x$-axis).',
        '対称軸は $x = 5$ で、そこで $y$ は最大の $25$ です。正しい：$x = 2$ と $x = 8$ は軸から等しい距離（$3$）なので利益が等しく、頂点は $x = 5$ での $25$ 百万。誤り：$x = 3$ と $x = 6$ は軸から等距離ではなく、$x = 5$ を過ぎると利益は下がり、$0$ と $10$ の間では利益は正（放物線が $x$ 軸の上にある）です。',
        '축은 $x = 5$ 이고 거기서 $y$ 의 최댓값이 $25$ 예요. 옳음: $x = 2$ 와 $x = 8$ 은 축에서 같은 거리($3$)라 이익이 같고, 정점은 $x = 5$ 에서 $25$ 백만이에요. 틀림: $x = 3$ 과 $x = 6$ 은 축에서 거리가 달라요. $x = 5$ 이후에는 이익이 줄고, $0$ 과 $10$ 사이에서는 이익이 양수예요(포물선이 $x$축 위에 있어요).'),
      { 3: ['openDir', { a: -1, dir: 'down' }] },
      { multi: 1, a: [0, 1] }),

    MC(2,
      X('Tabel parabola $y = ax^2 + bx + c$: $x = -2, -1, 0, 1, 2$ memberi $y = 17, 8, 1, -4, -7$. Pada $x$ berapa nilai $y$ terkecil dan berapa nilainya?',
        'Table of the parabola $y = ax^2 + bx + c$: $x = -2, -1, 0, 1, 2$ gives $y = 17, 8, 1, -4, -7$. At which $x$ is $y$ smallest, and what is its value?',
        '放物線 $y = ax^2 + bx + c$ の表：$x = -2, -1, 0, 1, 2$ のとき $y = 17, 8, 1, -4, -7$。$y$ が最小になる $x$ とその値は？',
        '포물선 $y = ax^2 + bx + c$ 의 표: $x = -2, -1, 0, 1, 2$ 일 때 $y = 17, 8, 1, -4, -7$. $y$ 가 가장 작은 $x$ 와 그 값은?'),
      ['$x = 3$, $y = -8$', '$x = 2$, $y = -7$', '$x = -3$, $y = -8$', '$x = 6$, $y = 1$'],
      X('Nilai $y$ di tabel masih turun, jadi puncak (titik terendah) mungkin di luar tabel. Cari $a$, $b$, $c$ dari tabel selisih, lalu hitung sumbunya.',
        'The $y$-values in the table are still falling, so the lowest point may be outside the table. Find $a$, $b$, $c$ from the difference table, then compute the axis.',
        '表の $y$ はまだ下がっているので、最も低い点は表の外にあるかもしれません。階差の表から $a$、$b$、$c$ を求め、軸を計算しましょう。',
        '표의 $y$ 값이 아직 내려가고 있으니 가장 낮은 점은 표 밖에 있을 수 있어요. 차이 표에서 $a$, $b$, $c$ 를 구한 뒤 축을 계산하세요.'),
      X('Selisih pertama: $-9, -7, -5, -3$; selisih kedua: $2$, jadi $a = 1$. $c = y(0) = 1$, dan $x = 1$: $1 + b + 1 = -4$ sehingga $b = -6$. Sumbu: $x = -\\dfrac{-6}{2} = 3$ (di luar tabel). Nilai terkecil: $y = 9 - 18 + 1 = -8$.',
        'First differences: $-9, -7, -5, -3$; second difference: $2$, so $a = 1$. $c = y(0) = 1$, and at $x = 1$: $1 + b + 1 = -4$ so $b = -6$. Axis: $x = -\\dfrac{-6}{2} = 3$ (outside the table). Smallest value: $y = 9 - 18 + 1 = -8$.',
        '1階差：$-9, -7, -5, -3$、2階差：$2$ なので $a = 1$。$c = y(0) = 1$、$x = 1$ で $1 + b + 1 = -4$ より $b = -6$。軸：$x = -\\dfrac{-6}{2} = 3$（表の外）。最小値：$y = 9 - 18 + 1 = -8$。',
        '일계 차이: $-9, -7, -5, -3$, 이계 차이: $2$ 이므로 $a = 1$. $c = y(0) = 1$, $x = 1$ 에서 $1 + b + 1 = -4$ 이므로 $b = -6$. 축: $x = -\\dfrac{-6}{2} = 3$ (표 밖). 최솟값: $y = 9 - 18 + 1 = -8$.'),
      { 2: ['axisSign', { x: 3, wx: -3 }], 3: ['axisIsB', { a: 1, b: -6, x: 3 }] }),
    MC(2,
      X('Energi perisai $E$ (dalam ribuan mana) tiap menit $t$: $t = 0, 1, 2, 3, 4$ memberi $E = 3, 10, 13, 12, 7$. Model kuadrat dan puncak energinya adalah...',
        'The shield energy $E$ (in thousands of mana) each minute $t$: $t = 0, 1, 2, 3, 4$ gives $E = 3, 10, 13, 12, 7$. The quadratic model and the energy peak are...',
        'シールドのエネルギー $E$（マナ千単位）を毎分 $t$ で測ると、$t = 0, 1, 2, 3, 4$ のとき $E = 3, 10, 13, 12, 7$ でした。二次モデルとエネルギーのピークは…',
        '방어막 에너지 $E$(마나 천 단위)를 매분 $t$ 마다 재면 $t = 0, 1, 2, 3, 4$ 일 때 $E = 3, 10, 13, 12, 7$ 이었어요. 이차 모델과 에너지 정점은...'),
      [X('$a = -2$, $c = 3$, puncak antara menit ke-2 dan ke-3', '$a = -2$, $c = 3$, peak between minute 2 and minute 3', '$a = -2$、$c = 3$、ピークは2分と3分の間', '$a = -2$, $c = 3$, 정점은 2분과 3분 사이'),
        X('$a = -4$, $c = 3$, puncak antara menit ke-2 dan ke-3', '$a = -4$, $c = 3$, peak between minute 2 and minute 3', '$a = -4$、$c = 3$、ピークは2分と3分の間', '$a = -4$, $c = 3$, 정점은 2분과 3분 사이'),
        X('$a = -2$, $c = 10$, puncak antara menit ke-2 dan ke-3', '$a = -2$, $c = 10$, peak between minute 2 and minute 3', '$a = -2$、$c = 10$、ピークは2分と3分の間', '$a = -2$, $c = 10$, 정점은 2분과 3분 사이'),
        X('$a = -2$, $c = 3$, puncak tepat di menit ke-2', '$a = -2$, $c = 3$, peak exactly at minute 2', '$a = -2$、$c = 3$、ピークはちょうど2分', '$a = -2$, $c = 3$, 정점은 정확히 2분')],
      X('Hitung selisih pertama dan kedua. Ingat selisih kedua $= 2a$, dan $c$ adalah nilai saat $t = 0$. Lalu cari sumbu dengan $-\\dfrac{b}{2a}$.',
        'Compute the first and second differences. Remember the second difference $= 2a$, and $c$ is the value at $t = 0$. Then find the axis with $-\\dfrac{b}{2a}$.',
        '1階差と2階差を計算しましょう。2階差は $2a$ に等しく、$c$ は $t = 0$ のときの値です。そのあと $-\\dfrac{b}{2a}$ で軸を求めます。',
        '일계 차이와 이계 차이를 구하세요. 이계 차이는 $2a$ 이고 $c$ 는 $t = 0$ 일 때의 값이에요. 그다음 $-\\dfrac{b}{2a}$ 로 축을 구하세요.'),
      X('Selisih pertama: $7, 3, -1, -5$; selisih kedua: $-4$, jadi $2a = -4$ dan $a = -2$. $c = E(0) = 3$. Dari $t = 1$: $-2 + b + 3 = 10$ sehingga $b = 9$. Sumbu $t = -\\dfrac{9}{2(-2)} = 2{,}25$, yaitu antara menit ke-2 dan ke-3 (puncak $E(2{,}25) = 13{,}125$, sedikit di atas $13$).',
        'First differences: $7, 3, -1, -5$; second difference: $-4$, so $2a = -4$ and $a = -2$. $c = E(0) = 3$. From $t = 1$: $-2 + b + 3 = 10$ so $b = 9$. Axis $t = -\\dfrac{9}{2(-2)} = 2{,}25$, which lies between minute 2 and minute 3 (peak $E(2{,}25) = 13{,}125$, slightly above $13$).',
        '1階差：$7, 3, -1, -5$、2階差：$-4$ なので $2a = -4$、$a = -2$。$c = E(0) = 3$。$t = 1$ より $-2 + b + 3 = 10$ なので $b = 9$。軸 $t = -\\dfrac{9}{2(-2)} = 2{,}25$ は2分と3分の間にあります（ピーク $E(2{,}25) = 13{,}125$ は $13$ をわずかに上回る）。',
        '일계 차이: $7, 3, -1, -5$, 이계 차이: $-4$ 이므로 $2a = -4$, $a = -2$. $c = E(0) = 3$. $t = 1$ 에서 $-2 + b + 3 = 10$ 이므로 $b = 9$. 축 $t = -\\dfrac{9}{2(-2)} = 2{,}25$ 는 2분과 3분 사이예요(정점 $E(2{,}25) = 13{,}125$ 는 $13$ 보다 조금 커요).')),

    FL(3,
      X('Parabola $y = ax^2 + bx + c$ memotong sumbu $y$ di $(0, -3)$, melalui titik $(1, 0)$, dan sumbu simetrinya $x = 2$. Tentukan $a$, $b$, dan nilai maksimumnya.',
        'The parabola $y = ax^2 + bx + c$ crosses the $y$-axis at $(0, -3)$, passes through $(1, 0)$, and has axis of symmetry $x = 2$. Find $a$, $b$, and its maximum value.',
        '放物線 $y = ax^2 + bx + c$ は $y$ 軸と $(0, -3)$ で交わり、点 $(1, 0)$ を通り、対称軸は $x = 2$ です。$a$、$b$、および最大値を求めなさい。',
        '포물선 $y = ax^2 + bx + c$ 는 $y$축과 $(0, -3)$ 에서 만나고, 점 $(1, 0)$ 을 지나며, 대칭축은 $x = 2$ 예요. $a$, $b$, 그리고 최댓값을 구하세요.'),
      [{ l: '$a$', r: /^(a=)?-1$/ }, { l: '$b$', r: /^(b=)?4$/ },
        { l: X('Nilai maksimum', 'Maximum value', '最大値', '최댓값'), r: /^(y=)?1$/ }],
      '$a = -1,\\ b = 4,\\ y_{\\max} = 1$',
      X('Dari $y$-intercept, $c$ sudah diketahui. Dari sumbu simetri, hubungkan $b$ dengan $a$ lewat $-\\dfrac{b}{2a} = 2$, lalu gunakan titik $(1, 0)$.',
        'From the $y$-intercept, $c$ is already known. From the axis, link $b$ to $a$ through $-\\dfrac{b}{2a} = 2$, then use the point $(1, 0)$.',
        '$y$ 切片から $c$ はすでに分かっています。軸から $-\\dfrac{b}{2a} = 2$ で $b$ と $a$ を結び付け、点 $(1, 0)$ を使いましょう。',
        '$y$절편에서 $c$ 는 이미 알아요. 축에서 $-\\dfrac{b}{2a} = 2$ 로 $b$ 와 $a$ 를 연결한 뒤 점 $(1, 0)$ 을 쓰세요.'),
      X('$c = -3$. Sumbu: $-\\dfrac{b}{2a} = 2$ sehingga $b = -4a$. Titik $(1, 0)$: $a + b - 3 = 0$, yaitu $a - 4a = 3$, sehingga $a = -1$ dan $b = 4$. Fungsi $y = -x^2 + 4x - 3$ punya $y$ maksimum di $x = 2$: $-4 + 8 - 3 = 1$.',
        '$c = -3$. Axis: $-\\dfrac{b}{2a} = 2$ so $b = -4a$. Point $(1, 0)$: $a + b - 3 = 0$, that is $a - 4a = 3$, so $a = -1$ and $b = 4$. The function $y = -x^2 + 4x - 3$ has its maximum $y$ at $x = 2$: $-4 + 8 - 3 = 1$.',
        '$c = -3$。軸：$-\\dfrac{b}{2a} = 2$ より $b = -4a$。点 $(1, 0)$：$a + b - 3 = 0$、つまり $a - 4a = 3$ なので $a = -1$、$b = 4$。関数 $y = -x^2 + 4x - 3$ は $x = 2$ で $y$ が最大になり、$-4 + 8 - 3 = 1$。',
        '$c = -3$. 축: $-\\dfrac{b}{2a} = 2$ 이므로 $b = -4a$. 점 $(1, 0)$: $a + b - 3 = 0$, 즉 $a - 4a = 3$ 이므로 $a = -1$, $b = 4$. 함수 $y = -x^2 + 4x - 3$ 은 $x = 2$ 에서 $y$ 가 최대이고 $-4 + 8 - 3 = 1$.')),

    MC(4,
      X('Parabola $y = 2x^2 + bx + 7$ memiliki sumbu simetri $x = -3$. Nilai minimum fungsi ini adalah...',
        'The parabola $y = 2x^2 + bx + 7$ has axis of symmetry $x = -3$. The minimum value of this function is...',
        '放物線 $y = 2x^2 + bx + 7$ の対称軸は $x = -3$ です。この関数の最小値は…',
        '포물선 $y = 2x^2 + bx + 7$ 의 대칭축은 $x = -3$ 이에요. 이 함수의 최솟값은...'),
      ['$-11$', '$61$', '$7$', '$-3$'],
      X('Gunakan $x = -\\dfrac{b}{2a}$ dengan $a = 2$ untuk mencari $b$ lebih dulu. Nilai minimum adalah nilai $y$ di sumbu, bukan nilai $x$-nya.',
        'Use $x = -\\dfrac{b}{2a}$ with $a = 2$ to find $b$ first. The minimum value is the $y$-value at the axis, not its $x$-value.',
        'まず $a = 2$ として $x = -\\dfrac{b}{2a}$ を使い $b$ を求めます。最小値は軸での $y$ の値であり、$x$ の値ではありません。',
        '먼저 $a = 2$ 로 $x = -\\dfrac{b}{2a}$ 를 써서 $b$ 를 구하세요. 최솟값은 축에서의 $y$ 값이지 $x$ 값이 아니에요.'),
      X('$-\\dfrac{b}{2 \\cdot 2} = -3$ sehingga $b = 12$. Karena $a \\gt 0$, nilai minimum ada di sumbu: $f(-3) = 2(9) + 12(-3) + 7 = 18 - 36 + 7 = -11$.',
        '$-\\dfrac{b}{2 \\cdot 2} = -3$ so $b = 12$. Since $a \\gt 0$, the minimum is on the axis: $f(-3) = 2(9) + 12(-3) + 7 = 18 - 36 + 7 = -11$.',
        '$-\\dfrac{b}{2 \\cdot 2} = -3$ より $b = 12$。$a \\gt 0$ なので最小値は軸上にあります：$f(-3) = 2(9) + 12(-3) + 7 = 18 - 36 + 7 = -11$。',
        '$-\\dfrac{b}{2 \\cdot 2} = -3$ 이므로 $b = 12$. $a \\gt 0$ 이므로 최솟값은 축 위에 있어요: $f(-3) = 2(9) + 12(-3) + 7 = 18 - 36 + 7 = -11$.'),
      { 1: ['axisSign', { x: -3, wx: 3 }], 2: ['axisNoHalf', { x: -3 }] }),
  ]);
})();
